package java;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

/**
 * Step 8: 동시성 처리 (Concurrency)
 *
 * <p>동시성 처리는 여러 스레드가 동시에 실행될 때 발생하는 문제들을 올바르게 해결하고 성능을 최적화하는 방법을 다룹니다.</p>
 * <p>{@code synchronized} 키워드의 한계를 이해하고, {@code java.util.concurrent} 패키지의 {@code ExecutorService}나 {@code Lock} 등을 사용한 현대적인 동시성 처리 방법을 학습합니다.</p>
 * <p>{@code volatile}, {@code Atomic} 클래스, {@code CompletableFuture} 등도 다룰 수 있습니다.</p>
 */
public class Step8_Concurrency {

    /**
     * 나쁜 예시: {@code synchronized} 블록 없이 여러 스레드에서 공유 변수를 직접 수정
     *
     * <p>설명: 이 예시에서는 여러 스레드가 동시에 {@code sharedCounter} 변수를 증가시킵니다.</p>
     * <p>{@code synchronized} 키워드나 {@code Lock}을 사용하지 않기 때문에, 증감 연산이 원자적(atomic)으로 이루어지지 않아 경쟁 조건(Race Condition)이 발생합니다.</p>
     * <p>결과적으로 최종 {@code sharedCounter} 값은 예상치 못한, 일관되지 않은 값을 가지게 됩니다.</p>
     */
    private static class BadCounter {
        private int sharedCounter = 0;

        public void increment() {
            sharedCounter++;
        }

        public int getSharedCounter() {
            return sharedCounter;
        }

        public void runBadExample() throws InterruptedException {
            System.out.println("--- Bad Example: Unsafe Counter ---");
            sharedCounter = 0; // Reset for demonstration
            ExecutorService service = Executors.newFixedThreadPool(10);

            for (int i = 0; i < 1000; i++) {
                service.submit(this::increment);
            }

            service.shutdown();
            service.awaitTermination(1, TimeUnit.MINUTES);

            // 예상보다 작은 값이 출력될 가능성이 높음
            System.out.println("Final Shared Counter (Bad): " + sharedCounter);
            System.out.println("Expected: 1000. Actual: " + sharedCounter + " (Likely incorrect due to race condition)");
            System.out.println("------------------------------------");
        }
    }

    /**
     * 좋은 예시 1: {@code AtomicInteger}를 사용한 안전한 카운터
     *
     * <p>설명: {@code AtomicInteger}는 내부적으로 CAS(Compare-And-Swap) 연산을 사용하여 스레드 안전성을 보장합니다.</p>
     * <p>별도의 명시적인 락(lock) 메커니즘 없이도 원자적인 연산이 가능하여 경쟁 조건을 방지하고 정확한 결과를 얻을 수 있습니다.</p>
     * <p>성능 면에서도 {@code synchronized} 블록보다 우수할 수 있습니다.</p>
     */
    private static class GoodCounterAtomic {
        private final AtomicInteger sharedCounter = new AtomicInteger(0);

        public void increment() {
            sharedCounter.incrementAndGet();
        }

        public int getSharedCounter() {
            return sharedCounter.get();
        }

        public void runGoodExample() throws InterruptedException {
            System.out.println("--- Good Example 1: AtomicInteger ---");
            sharedCounter.set(0); // Reset for demonstration
            ExecutorService service = Executors.newFixedThreadPool(10);

            for (int i = 0; i < 1000; i++) {
                service.submit(this::increment);
            }

            service.shutdown();
            service.awaitTermination(1, TimeUnit.MINUTES);

            // 항상 1000이 출력됨
            System.out.println("Final Shared Counter (Good - Atomic): " + sharedCounter.get());
            System.out.println("Expected: 1000. Actual: " + sharedCounter.get() + " (Correct)");
            System.out.println("---------------------------------------");
        }
    }

    /**
     * 좋은 예시 2: {@code ReentrantLock}을 사용한 안전한 카운터
     *
     * <p>설명: {@code ReentrantLock}은 {@code synchronized} 키워드보다 더 유연하고 정교한 락킹 메커니즘을 제공합니다.</p>
     * <p>명시적으로 {@code lock()}과 {@code unlock()}을 호출하여 임계 영역(Critical Section)을 보호하며, 락 획득 시도 및 타임아웃 설정 등 다양한 기능을 제공합니다.</p>
     * <p>{@code finally} 블록에서 {@code unlock()}을 호출하여 락이 항상 해제되도록 하는 것이 중요합니다.</p>
     */
    private static class GoodCounterLock {
        private int sharedCounter = 0;
        private final Lock lock = new ReentrantLock();

        public void increment() {
            lock.lock(); // 락 획득
            try {
                sharedCounter++;
            } finally {
                lock.unlock(); // 락 해제 (항상 해제되도록 finally 블록에 위치)
            }
        }

        public int getSharedCounter() {
            lock.lock(); // 읽기 작업도 보호해야 함
            try {
                return sharedCounter;
            } finally {
                lock.unlock();
            }
        }

        public void runGoodExample() throws InterruptedException {
            System.out.println("--- Good Example 2: ReentrantLock ---");
            sharedCounter = 0; // Reset for demonstration
            ExecutorService service = Executors.newFixedThreadPool(10);

            for (int i = 0; i < 1000; i++) {
                service.submit(this::increment);
            }

            service.shutdown();
            service.awaitTermination(1, TimeUnit.MINUTES);

            // 항상 1000이 출력됨
            System.out.println("Final Shared Counter (Good - Lock): " + getSharedCounter());
            System.out.println("Expected: 1000. Actual: " + getSharedCounter() + " (Correct)");
            System.out.println("---------------------------------------");
        }
    }

    /**
     * 메인 메소드: 동시성 처리의 나쁜 예시와 좋은 예시를 실행합니다.
     *
     * @param args 커맨드 라인 인자 (사용되지 않음)
     * @throws InterruptedException 스레드 실행 중 인터럽트 발생 시
     */
    public static void main(String[] args) throws InterruptedException {
        // 나쁜 예시 실행
        new BadCounter().runBadExample();

        // 좋은 예시 1 실행 (AtomicInteger)
        new GoodCounterAtomic().runGoodExample();

        // 좋은 예시 2 실행 (ReentrantLock)
        new GoodCounterLock().runGoodExample();
    }
}

// JavaScript 기본 문법
// 변수, 자료형, 연산자, 조건문, 반복문 등 ES6+ 기본 문법 이해

// 나쁜 예시: `var` 키워드를 사용하여 변수를 선언하고, 전역 스코프 오염이나 호이스팅 문제를 야기합니다.
// 좋은 예시: `let`과 `const` 키워드를 사용하여 블록 스코프를 준수하고, 변수의 재할당 여부를 명확히 합니다.

// --- 변수 선언 ---
// var (나쁜 예시) - 재선언, 재할당 가능, 함수 스코프
var oldVar = "옛날 변수";
var oldVar = "재선언도 가능";
oldVar = "재할당도 가능";
console.log("var:", oldVar);

// let (좋은 예시) - 재선언 불가, 재할당 가능, 블록 스코프
let newLet = "새로운 변수";
// let newLet = "재선언 불가"; // SyntaxError: 'newLet' has already been declared
newLet = "재할당 가능";
console.log("let:", newLet);

// const (좋은 예시) - 재선언 불가, 재할당 불가, 블록 스코프 (상수)
const newConst = "상수 변수";
// const newConst = "재선언 불가"; // SyntaxError: 'newConst' has already been declared
// newConst = "재할당 불가"; // TypeError: Assignment to constant variable.
console.log("const:", newConst);

// --- 자료형 ---
// 원시 자료형 (Primitives)
let str = "Hello, JavaScript!"; // 문자열 (String)
let num = 123; // 숫자 (Number) - 정수 및 실수 모두 포함
let floatNum = 123.45;
let bool = true; // 불리언 (Boolean)
let undef = undefined; // Undefined - 값이 할당되지 않은 상태
let nul = null; // Null - 의도적으로 값이 없음을 나타냄
let sym = Symbol('id'); // Symbol - ES6에서 추가된 유일한 값
let bigInt = 1234567890123456789012345678901234567890n; // BigInt - ES2020에서 추가된 임의 정밀도의 정수

console.log("자료형:", typeof str, typeof num, typeof bool, typeof undef, typeof nul, typeof sym, typeof bigInt);

// 객체 자료형 (Object)
let obj = { name: "Alice", age: 30 }; // 객체 (Object)
let arr = [1, 2, 3]; // 배열 (Array) - 객체의 일종
let func = function() {}; // 함수 (Function) - 객체의 일종

console.log("객체 자료형:", typeof obj, typeof arr, typeof func);

// --- 연산자 ---
// 산술 연산자: +, -, *, /, %, **
console.log("산술 연산:", 10 + 3, 10 - 3, 10 * 3, 10 / 3, 10 % 3, 2 ** 3);

// 할당 연산자: =, +=, -=, *=, /=, %=, **=
let x = 10;
x += 5; // x = x + 5;
console.log("할당 연산:", x);

// 비교 연산자: ==, ===, !=, !==, <, >, <=, >=
console.log("비교 연산 (동등):", 10 == '10', 10 === '10'); // == 값만 비교, === 값과 타입 모두 비교
console.log("비교 연산 (부등):", 10 != '10', 10 !== '10');
console.log("비교 연산 (크기):", 10 > 5, 10 <= 10);

// 논리 연산자: && (AND), || (OR), ! (NOT)
console.log("논리 연산:", true && false, true || false, !true);

// --- 조건문 (if, else if, else) ---
let score = 85;
if (score >= 90) {
    console.log("A 학점");
} else if (score >= 80) {
    console.log("B 학점");
} else {
    console.log("C 학점 이하");
}

// switch 문
let day = '월요일';
switch (day) {
    case '월요일':
        console.log("한 주의 시작!");
        break;
    case '금요일':
        console.log("불금!");
        break;
    default:
        console.log("평범한 요일");
}

// --- 반복문 (for, while, do...while, for...of, for...in) ---
// for 루프
for (let i = 0; i < 3; i++) {
    console.log("for 루프:", i);
}

// while 루프
let i = 0;
while (i < 3) {
    console.log("while 루프:", i);
    i++;
}

// do...while 루프 (최소 한 번은 실행)
let j = 0;
do {
    console.log("do...while 루프:", j);
    j++;
} while (j < 3);

// for...of (이터러블 객체 순회: 배열, 문자열 등)
const colors = ['red', 'green', 'blue'];
for (const color of colors) {
    console.log("for...of:", color);
}

// for...in (객체의 속성 이름 순회)
const car = { brand: 'Hyundai', model: 'Sonata' };
for (const key in car) {
    console.log(`for...in: ${key}: ${car[key]}`);
}

// --- 템플릿 리터럴 (Template Literals) ---
// 백틱(``)을 사용하여 문자열 내부에 변수나 표현식을 쉽게 포함할 수 있습니다.
const product = "노트북";
const price = 1200000;
console.log(`제품: ${product}, 가격: ${price}원`);

// --- 화살표 함수 (Arrow Functions) ---
// 함수를 더 간결하게 작성할 수 있는 ES6 문법
const addNumbers = (a, b) => a + b;
console.log("화살표 함수 덧셈:", addNumbers(5, 7));

// --- 스프레드 연산자 (...) ---
// 배열이나 객체를 복사하거나 병합할 때 유용
const arr1 = [1, 2, 3];
const arr2 = [...arr1, 4, 5]; // [1, 2, 3, 4, 5]
console.log("스프레드 연산자 (배열):", arr2);

const obj1 = { a: 1, b: 2 };
const obj2 = { ...obj1, c: 3 }; // { a: 1, b: 2, c: 3 }
console.log("스프레드 연산자 (객체):", obj2);

// JavaScript 함수와 스코프
// 함수 선언/표현식, 화살표 함수, 클로저, 스코프 체인 학습

// 나쁜 예시: 전역 변수를 과도하게 사용하거나, 스코프를 고려하지 않아 변수 충돌 및 유지보수 어려움.
// 좋은 예시: 각 스코프의 규칙을 이해하고, 클로저 등을 활용하여 데이터를 안전하게 캡슐화.

// --- 함수 선언식 (Function Declaration) ---
// 호이스팅(Hoisting) 발생: 함수가 선언되기 전에 호출 가능
console.log(declareFunction()); // "함수 선언식 호출"
function declareFunction() {
    return "함수 선언식 호출";
}

// --- 함수 표현식 (Function Expression) ---
// 호이스팅 발생 안 함: 함수가 정의된 후에만 호출 가능
// console.log(expressFunction()); // TypeError: expressFunction is not a function
const expressFunction = function() {
    return "함수 표현식 호출";
};
console.log(expressFunction());

// --- 화살표 함수 (Arrow Function) ---
// 간결한 문법, 항상 익명 함수, 자신만의 this, arguments, super, new.target 없음
const arrowFunction = () => "화살표 함수 호출";
console.log(arrowFunction());

const multiply = (a, b) => a * b;
console.log("곱셈 (화살표 함수):", multiply(5, 3));

// --- 스코프 (Scope) ---
// 1. 전역 스코프 (Global Scope)
let globalVar = "전역 변수";

function outerFunction() {
    // 2. 함수 스코프 (Function Scope) - var 키워드
    var functionScopedVar = "함수 스코프 변수";
    console.log("outerFunction 내부 - 전역 변수:", globalVar);
    console.log("outerFunction 내부 - 함수 스코프 변수:", functionScopedVar);

    if (true) {
        // 3. 블록 스코프 (Block Scope) - let, const 키워드
        let blockScopedVar = "블록 스코프 변수";
        console.log("if 블록 내부 - 전역 변수:", globalVar);
        console.log("if 블록 내부 - 함수 스코프 변수:", functionScopedVar);
        console.log("if 블록 내부 - 블록 스코프 변수:", blockScopedVar);
    }
    // console.log("outerFunction 내부 - 블록 스코프 변수:", blockScopedVar); // ReferenceError: blockScopedVar is not defined
}

outerFunction();
console.log("전역 - 전역 변수:", globalVar);
// console.log("전역 - 함수 스코프 변수:", functionScopedVar); // ReferenceError: functionScopedVar is not defined

// --- 스코프 체인 (Scope Chain) ---
// 함수는 자신이 정의된 스코프(렉시컬 스코프)를 기억하고, 해당 스코프의 상위 스코프에 접근할 수 있습니다.
let x = 10; // 전역 스코프

function foo() {
    let y = 20; // foo 스코프
    function bar() {
        let z = 30; // bar 스코프
        console.log("bar 내부:", x + y + z); // 10 + 20 + 30 = 60
    }
    bar();
}
foo();

// --- 클로저 (Closure) ---
// 함수와 함수가 선언된 렉시컬 환경의 조합.
// 외부 함수의 실행이 끝나더라도 외부 함수의 변수에 접근할 수 있는 내부 함수.
function makeCounter() {
    let count = 0; // makeCounter의 렉시컬 환경에 속한 변수
    return function() { // 클로저 함수
        count++;
        return count;
    };
}

const counter1 = makeCounter();
console.log("Counter1:", counter1()); // 1
console.log("Counter1:", counter1()); // 2

const counter2 = makeCounter(); // 새로운 렉시컬 환경 생성
console.log("Counter2:", counter2()); // 1
console.log("Counter1:", counter1()); // 3 (counter1은 자신만의 count를 유지)

// 클로저를 이용한 정보 은닉
function createPerson(name) {
    let _name = name; // private 변수처럼 사용

    return {
        getName: function() {
            return _name;
        },
        setName: function(newName) {
            _name = newName;
        }
    };
}

const person = createPerson("김철수");
console.log("Person 이름:", person.getName()); // 김철수
person.setName("이영희");
console.log("Person 변경된 이름:", person.getName()); // 이영희
// console.log(person._name); // Undefined, 외부에서 직접 접근 불가

// JavaScript 비동기 처리
// Callback, Promise, Async/Await를 이용한 비동기 프로그래밍 학습

// 나쁜 예시: 콜백 헬(Callback Hell)로 인해 코드 가독성이 떨어지고 유지보수가 어려움.
// 좋은 예시: Promise와 Async/Await를 사용하여 비동기 코드를 동기 코드처럼 읽기 쉽게 작성하고 오류 처리를 명확하게 함.

// --- 1. Callback (콜백) ---
// 비동기 작업이 완료되면 실행될 함수를 인자로 넘기는 방식
console.log("--- Callback 예시 ---");
function fetchData(callback) {
    setTimeout(() => {
        const data = "데이터 가져오기 성공!";
        callback(data); // 데이터 가져온 후 콜백 함수 호출
    }, 1000);
}

function processData(data, callback) {
    setTimeout(() => {
        const processedData = data.toUpperCase();
        callback(processedData);
    }, 500);
}

function displayData(processedData) {
    console.log("콜백 최종 결과:", processedData);
}

// 콜백 헬 예시 (나쁜 예시)
// fetchData((data) => {
//     processData(data, (processedData) => {
//         displayData(processedData);
//     });
// });


// --- 2. Promise (프로미스) ---
// 비동기 작업의 최종 완료 또는 실패를 나타내는 객체
console.log("\n--- Promise 예시 ---");

function fetchDataPromise() {
    return new Promise((resolve, reject) => {
        setTimeout(() => {
            const success = true; // 가상으로 성공/실패 여부 결정
            if (success) {
                resolve("데이터 가져오기 성공 (Promise)!"); // 성공 시 resolve 호출
            } else {
                reject("데이터 가져오기 실패 (Promise)!"); // 실패 시 reject 호출
            }
        }, 1000);
    });
}

function processDataPromise(data) {
    return new Promise((resolve) => {
        setTimeout(() => {
            resolve(data.toUpperCase());
        }, 500);
    });
}

// Promise 체이닝 (좋은 예시)
fetchDataPromise()
    .then((data) => {
        console.log("1단계 Promise:", data);
        return processDataPromise(data);
    })
    .then((processedData) => {
        console.log("2단계 Promise:", processedData);
        console.log("Promise 최종 결과:", processedData);
    })
    .catch((error) => { // 체인 중 발생한 모든 에러를 한 번에 처리
        console.error("Promise 오류:", error);
    });


// --- 3. Async/Await (비동기/대기) ---
// Promise를 더 쉽고 동기 코드처럼 보이게 작성하는 ES2017 문법
console.log("\n--- Async/Await 예시 ---");

async function fetchDataAsync() {
    return new Promise((resolve) => {
        setTimeout(() => {
            resolve("데이터 가져오기 성공 (Async/Await)!");
        }, 1200);
    });
}

async function processDataAsync(data) {
    return new Promise((resolve) => {
        setTimeout(() => {
            resolve(data.toUpperCase());
        }, 600);
    });
}

async function performAsyncTask() {
    try {
        const data = await fetchDataAsync(); // Promise가 resolve될 때까지 기다림
        console.log("1단계 Async/Await:", data);
        const processedData = await processDataAsync(data);
        console.log("2단계 Async/Await:", processedData);
        console.log("Async/Await 최종 결과:", processedData);
    } catch (error) { // try-catch 블록으로 에러 처리
        console.error("Async/Await 오류:", error);
    }
}

performAsyncTask();

