// 생명 주기 어노테이션을 사용하는 함수
fn longest<'a>(x: &'a str, y: &'a str) -> &'a str {
    if x.len() > y.len() {
        x
    } else {
        y
    }
}

// Rust Step 3: 구조체와 열거형 (Structs & Enums)
// 사용자 정의 타입을 정의하고 패턴 매칭을 통해 데이터 처리

// 나쁜 예시: 관련된 데이터들을 개별 변수로 관리하여 코드의 응집도를 떨어뜨리고,
// 여러 가지 상태를 마법의 숫자나 문자열로 표현하여 가독성 저해.
// 좋은 예시: 구조체를 사용하여 관련된 데이터들을 하나의 단위로 묶고,
// 열거형을 사용하여 가능한 값의 집합을 명확히 정의하여 타입 안전성과 가독성을 높임.

// 학습 포인트: 구조체와 열거형은 Rust에서 복잡한 데이터를 모델링하는 기본 블록입니다.

// --- 1. 구조체 (Structs) ---
// 관련된 데이터들을 이름으로 묶어 하나의 사용자 정의 타입을 만듭니다.

// 1-1. 필드(field)를 가진 구조체
#[derive(Debug)] // 디버그 출력을 위한 Trait 자동 구현
struct User {
    active: bool,
    username: String,
    email: String,
    sign_in_count: u64,
}

fn main() {
    let user1 = User {
        active: true,
        username: String::from("someuser123"),
        email: String::from("someone@example.com"),
        sign_in_count: 1,
    };

    println!("사용자 1 이름: {}", user1.username);
    // user1.active = false; // 에러: 구조체 인스턴스는 기본적으로 불변입니다.
    // user1.username = String::from("anotheruser"); // 에러: 구조체 인스턴스는 기본적으로 불변입니다.

    // 가변 구조체 인스턴스
    let mut user2 = User {
        active: true,
        username: String::from("anotheruser456"),
        email: String::from("another@example.com"),
        sign_in_count: 5,
    };
    user2.active = false; // 가변이므로 변경 가능
    user2.email = String::from("newemail@example.com");
    println!("사용자 2의 새 이메일: {}", user2.email);

    // 구조체 업데이트 문법 (Struct Update Syntax)
    // 기존 구조체의 일부 필드만 변경하고 싶을 때 유용
    let user3 = User {
        email: String::from("third@example.com"),
        ..user1 // user1의 나머지 필드들을 복사 (user1의 소유권은 이동됨)
    };
    // println!("User1: {:?}", user1); // 에러: user1의 소유권이 user3으로 이동됨.
    println!("User3: {:?}", user3); // {:?}는 Debug Trait을 사용하여 구조체 전체를 출력

    // 1-2. 튜플 구조체 (Tuple Structs)
    // 이름 없는 필드를 가진 튜플과 유사한 구조체. 주로 튜플에 이름을 부여할 때 사용.
    struct Color(i32, i32, i32);
    struct Point(i32, i32, i32);

    let black = Color(0, 0, 0);
    let origin = Point(0, 0, 0);
    // let x = black; // 에러: 서로 다른 타입의 튜플 구조체이므로 직접 대입 불가

    // 1-3. 유닛-라이크 구조체 (Unit-Like Structs)
    // 필드가 없는 구조체. 주로 Trait을 구현할 때 사용.
    struct AlwaysEqual;
    let subject = AlwaysEqual;

    // --- 2. 열거형 (Enums) ---
    // 특정 값들 중 하나를 나타내는 타입을 정의합니다.

    // 2-1. 단순 열거형
    enum IpAddrKind {
        V4,
        V6,
    }

    let four = IpAddrKind::V4;
    let six = IpAddrKind::V6;

    // 2-2. 열거형에 데이터 포함
    // 열거형의 각 variant(변형)에 서로 다른 타입의 데이터를 직접 저장할 수 있습니다.
    #[derive(Debug)]
    enum IpAddr {
        V4(String), // V4 variant는 String을 가집니다.
        V6(String), // V6 variant도 String을 가집니다.
    }

    let home = IpAddr::V4(String::from("127.0.0.1"));
    let loopback = IpAddr::V6(String::from("::1"));
    println!("홈 주소: {:?}", home);
    println!("루프백 주소: {:?}", loopback);

    // 더 복잡한 열거형 예시: 메시지 타입
    #[derive(Debug)]
    enum Message {
        Quit,                            // 데이터 없음
        Move { x: i32, y: i32 },         // 익명 구조체 포함
        Write(String),                   // String 포함
        ChangeColor(i32, i32, i32),      // 튜플 포함
    }

    let m1 = Message::Quit;
    let m2 = Message::Move { x: 10, y: 20 };
    let m3 = Message::Write(String::from("hello"));
    let m4 = Message::ChangeColor(255, 0, 0);

    println!("메시지: {:?}, {:?}, {:?}, {:?}", m1, m2, m3, m4);

    // 2-3. `impl`을 이용한 열거형 메서드
    impl Message {
        fn call(&self) {
            match self {
                Message::Quit => println!("Quit 메시지 호출."),
                Message::Move { x, y } => println!("Move 메시지 호출: x={}, y={}", x, y),
                Message::Write(text) => println!("Write 메시지 호출: {}", text),
                Message::ChangeColor(r, g, b) => println!("ChangeColor 메시지 호출: r={}, g={}, b={}", r, g, b),
            }
        }
    }
    m2.call();
    m3.call();

    // --- 3. `match` 표현식과 패턴 매칭 (Pattern Matching) ---
    // 열거형 값을 처리할 때 `match` 표현식을 사용하여 가능한 모든 variant를 처리합니다.
    // `match`는 철저해야 합니다 (모든 경우를 커버해야 함).
    fn route(ip_kind: IpAddrKind) {
        match ip_kind {
            IpAddrKind::V4 => println!("IPv4 주소입니다."),
            IpAddrKind::V6 => println!("IPv6 주소입니다."),
        }
    }
    route(four);
    route(six);

    // `Option` 열거형 (표준 라이브러리)
    // `Option<T>`는 값이 있거나 없을 수 있음을 나타내는 열거형.
    // `Some(T)`: 값이 존재함. `None`: 값이 없음.
    // 이는 다른 언어의 `null` 개념을 안전하게 처리하는 Rust 방식입니다.
    let some_number = Some(5);
    let some_char = Some('e');
    let no_number: Option<i32> = None; // None을 사용할 때는 타입을 명시해야 합니다.

    // `match`와 `Option`
    fn plus_one_option(x: Option<i32>) -> Option<i32> {
        match x {
            None => None, // None이면 None 반환
            Some(i) => Some(i + 1), // Some(값)이면 값에 1을 더하여 Some으로 반환
        }
    }
    let five_opt = Some(5);
    let six_opt = plus_one_option(five_opt);
    let none_opt = plus_one_option(None);

    println!("five_opt: {:?}", five_opt);
    println!("six_opt: {:?}", six_opt);
    println!("none_opt: {:?}", none_opt);

    // `if let` (한 가지 경우만 처리하고 싶을 때)
    if let Some(value) = five_opt {
        println!("five_opt의 값: {}", value);
    } else {
        println!("five_opt는 None입니다.");
    }

    // 학습 포인트: 구조체와 열거형은 데이터 모델링과 타입 안전성 보장에 중요한 역할을 합니다.
    // 특히 열거형과 `match` 표현식은 강력한 패턴 매칭 기능을 제공하여 코드를 간결하고 안전하게 만듭니다.
    // `Option` 열거형을 통해 `null` 관련 오류를 컴파일 시점에 방지할 수 있습니다.
}

// Rust Step 4: 에러 처리 (Error Handling)
// `Result`와 `Option` 열거형을 이용한 견고한 에러 처리

// 나쁜 예시: 에러를 무시하거나 `panic!`을 남용하여 프로그램이 예상치 못하게 종료.
// 좋은 예시: `Option`과 `Result` 열거형을 사용하여 에러 발생 가능성을 명시하고,
// `match`, `if let`, `?` 연산자 등으로 에러를 예측 가능하고 안전하게 처리.

// 학습 포인트: Rust는 `null`이나 예외(Exception) 대신 `Option`과 `Result`라는 열거형을 통해 에러를 명시적으로 처리합니다.

use std::fs::File;
use std::io::{self, Read}; // io 모듈에서 self(모듈 자체)와 Read 트레잇을 가져옵니다.

fn main() {
    // --- 1. `panic!` (복구 불가능한 에러) ---
    // 복구할 수 없는 심각한 버그나 프로그램의 논리적 오류가 발생했을 때 사용합니다.
    // `panic!`이 호출되면 프로그램은 스택을 풀고 종료됩니다.
    // 일반적으로 라이브러리 개발 시 사용자가 잘못된 값을 전달할 때 사용됩니다.

    // panic!("복구 불가능한 에러 발생!"); // 이 코드가 실행되면 프로그램은 즉시 종료됩니다.

    // 배열 인덱스 초과 접근 시 `panic!` 발생 (Rust가 자동으로 처리)
    let v = vec![1, 2, 3];
    // v[99]; // 런타임에 panic! 발생: index out of bounds

    // --- 2. `Option<T>` (값이 없음을 표현) ---
    // 값이 존재할 수도 있고 (`Some(T)`), 존재하지 않을 수도 있음 (`None`).
    // 다른 언어의 `null`을 대체하는 안전한 방식.

    let some_number = Some(5); // Option<i32>
    let some_string = Some("a string"); // Option<&str>
    let no_number: Option<i32> = None; // None을 사용할 때는 타입을 명시해야 함

    // `match`를 사용하여 `Option` 값 처리 (철저해야 함)
    fn plus_one(x: Option<i32>) -> Option<i32> {
        match x {
            None => {
                println!("입력값이 None입니다.");
                None
            },
            Some(i) => {
                println!("입력값: {}", i);
                Some(i + 1)
            },
        }
    }

    let five = Some(5);
    let six = plus_one(five);
    let none = plus_one(None);
    println!("five: {:?}, six: {:?}, none: {:?}", five, six, none);

    // `if let`을 사용하여 특정 `Some` 값만 처리 (간결)
    if let Some(val) = five {
        println!("if let으로 얻은 값: {}", val);
    } else {
        println!("if let: 값이 없습니다.");
    }

    // `unwrap()`과 `expect()` (값 강제 추출)
    // `Some` 값을 강제로 추출합니다. `None`일 경우 `panic!` 발생.
    // `unwrap()`: `None`일 경우 기본 `panic!` 메시지.
    // `expect("메시지")`: `None`일 경우 지정된 메시지와 함께 `panic!`.
    let unwrapped_five = five.unwrap();
    println!("unwrap으로 얻은 값: {}", unwrapped_five);
    // let unwrapped_none = none.unwrap(); // 런타임에 panic! 발생
    // let expected_none = none.expect("이 값은 반드시 존재해야 합니다!"); // 런타임에 panic! 발생

    // --- 3. `Result<T, E>` (복구 가능한 에러 표현) ---
    // 성공적인 값 (`Ok(T)`) 또는 에러 (`Err(E)`) 중 하나를 반환할 수 있는 열거형.
    // 파일 입출력, 네트워크 통신 등 실패할 가능성이 있는 작업에 사용.

    // 파일 열기 예시 (`Result<File, Error>`)
    let greeting_file_result = File::open("hello.txt");

    let greeting_file = match greeting_file_result {
        Ok(file) => {
            println!("파일을 성공적으로 열었습니다.");
            file
        },
        Err(error) => match error.kind() {
            // 파일을 찾을 수 없을 때만 파일을 생성
            io::ErrorKind::NotFound => match File::create("hello.txt") {
                Ok(fc) => {
                    println!("hello.txt 파일을 생성했습니다.");
                    fc
                },
                Err(e) => panic!("파일 생성 실패: {:?}", e),
            },
            // 다른 종류의 에러는 `panic!`
            other_error => panic!("파일 열기 실패: {:?}", other_error),
        },
    };
    // greeting_file 변수를 사용하거나, 단순히 예외 처리 로직으로만 활용.


    // --- 4. 에러 전파 (Propagating Errors) ---
    // `?` 연산자를 사용하여 `Result` 값을 간결하게 처리하고 에러를 호출자에게 전파합니다.
    // `?`는 `Result::Err`이면 `return Err(e)`를, `Result::Ok`이면 `Ok` 값을 추출합니다.
    fn read_username_from_file() -> Result<String, io::Error> {
        let mut f = File::open("username.txt")?; // 에러 발생 시 즉시 반환
        let mut username = String::new();
        f.read_to_string(&mut username)?; // 에러 발생 시 즉시 반환
        Ok(username) // 성공 시 Ok 값 반환
    }

    // 위 함수와 동일한 `match` 표현식
    // fn read_username_from_file_verbose() -> Result<String, io::Error> {
    //     let f_result = File::open("username.txt");
    //     let mut f = match f_result {
    //         Ok(file) => file,
    //         Err(e) => return Err(e),
    //     };
    //     let mut username = String::new();
    //     match f.read_to_string(&mut username) {
    //         Ok(_) => Ok(username),
    //         Err(e) => Err(e),
    //     }
    // }

    let username_result = read_username_from_file();
    match username_result {
        Ok(name) => println!("사용자 이름: {}", name),
        Err(e) => println!("사용자 이름 읽기 실패: {:?}", e),
    }

    // `.map_err()` 또는 `.and_then()` 등을 활용한 에러 처리 (고급)
    // `std::fs::read_to_string` 함수는 위 코드를 더 간결하게 만듭니다.
    let username_simple_result = std::fs::read_to_string("username_simple.txt");
    match username_simple_result {
        Ok(name) => println!("간결한 사용자 이름: {}", name),
        Err(e) => println!("간결한 사용자 이름 읽기 실패: {:?}", e),
    }

    // 학습 포인트: Rust의 에러 처리 전략은 `Option`과 `Result` 열거형을 중심으로 컴파일 타임에 에러를 강제합니다.
    // `unwrap()`과 `expect()`는 개발 초기에 프로토타이핑을 위해 사용하거나, 복구할 수 없는 에러에만 사용하고,
    // 프로덕션 코드에서는 `match`, `if let`, `?` 연산자를 사용하여 에러를 명시적으로 처리하는 것이 중요합니다.
}

// Rust Step 5: 컬렉션 (Collections)
// `Vec`, `String`, `HashMap` 등 Rust 표준 라이브러리 컬렉션 활용

// 나쁜 예시: 고정 길이 배열만 사용하거나, 직접 복잡한 데이터 구조를 구현하여 비효율적인 코드 작성.
// 좋은 예시: Rust 표준 라이브러리에서 제공하는 컬렉션(`Vec`, `String`, `HashMap` 등)을 활용하여
// 데이터를 효율적으로 저장하고 관리하며, 타입 안전성을 유지.

// 학습 포인트: Rust의 컬렉션은 다양한 데이터 저장 및 관리 요구사항을 충족시키며, 소유권 규칙과 결합하여 안전한 메모리 관리를 제공합니다.

fn main() {
    // --- 1. `Vec<T>` (벡터) ---
    // 가변 길이의 동일한 타입 요소를 저장하는 컬렉션 (다른 언어의 ArrayList와 유사)
    println!("--- Vec<T> (벡터) ---");

    // 빈 벡터 생성
    let mut v: Vec<i32> = Vec::new(); // 타입 어노테이션 필요 (초기에는 비어있으므로 추론 불가)
    v.push(5);
    v.push(6);
    v.push(7);
    println!("벡터 v: {:?}", v);

    // `vec!` 매크로를 사용하여 초기화
    let mut v2 = vec![1, 2, 3]; // 타입 추론 가능
    println!("벡터 v2: {:?}", v2);

    // 요소 접근 (인덱싱)
    let third = &v2[2]; // 불변 참조
    println!("세 번째 요소: {}", third);

    // `get` 메서드를 사용한 안전한 접근 (`Option<T>`)
    match v2.get(2) {
        Some(third) => println!("get 메서드로 얻은 세 번째 요소: {}", third),
        None => println!("세 번째 요소가 없습니다."),
    }

    // 벡터 순회
    for i in &v2 { // 불변 참조로 순회
        println!("벡터 요소: {}", i);
    }
    for i in &mut v2 { // 가변 참조로 순회 (값 변경 가능)
        *i += 50; // 역참조하여 값 변경
    }
    println!("변경 후 벡터 v2: {:?}", v2);

    // --- 2. `String` (문자열) ---
    // 가변 길이의 UTF-8 인코딩 문자열 (힙에 저장)
    println!("\n--- String (문자열) ---");

    // 빈 String 생성
    let mut s = String::new();

    // `to_string()` 메서드로 `&str`에서 `String` 생성
    let s1 = "initial contents".to_string();
    let s2 = String::from("hello"); // String::from 함수

    s.push_str("foo"); // 문자열 리터럴을 추가
    s.push('b'); // 단일 문자를 추가
    println!("문자열 s: {}", s);

    // 문자열 연결
    let s3 = String::from("Hello, ");
    let s4 = String::from("world!");
    let s5 = s3 + &s4; // s3의 소유권은 s5로 이동합니다. s3는 더 이상 사용할 수 없습니다.
    // println!("s3: {}", s3); // 에러!
    println!("연결된 문자열 s5: {}", s5);

    // format! 매크로 (소유권 이동 없음)
    let tic = String::from("tic");
    let tac = String::from("tac");
    let toe = String::from("toe");
    let tictactoe = format!("{}-{}-{}", tic, tac, toe); // tic, tac, toe는 여전히 유효
    println!("format! 매크로: {}", tictactoe);

    // 문자열 인덱싱 (Rust에서는 인덱싱이 까다로움)
    // Rust의 String은 UTF-8로 인코딩되어 있어, 문자열을 바이트, 스칼라 값, grapheme cluster로 해석할 수 있습니다.
    // s5[0]; // 에러: String을 인덱싱할 수 없습니다.

    // 문자열 슬라이싱 (주의 필요)
    let hello = "안녕하세요"; // 15바이트 (한글 한 글자는 3바이트)
    // let s_slice = &hello[0..3]; // "안"
    // let s_slice_fail = &hello[0..2]; // 런타임 panic!: byte index is not on a character boundary

    // --- 3. `HashMap<K, V>` (해시맵) ---
    // 키-값 쌍을 저장하는 컬렉션 (다른 언어의 Hash Map, Dictionary와 유사)
    println!("\n--- HashMap<K, V> ---");

    use std::collections::HashMap;

    let mut scores = HashMap::new();

    // 값 삽입
    scores.insert(String::from("Blue"), 10);
    scores.insert(String::from("Yellow"), 50);
    println!("해시맵 scores: {:?}", scores);

    // 키를 통해 값 접근 (`Option<V>`)
    let team_name = String::from("Blue");
    let score = scores.get(&team_name); // 참조를 넘겨야 합니다.

    match score {
        Some(s) => println!("Blue 팀 점수: {}", s),
        None => println!("Blue 팀 점수를 찾을 수 없습니다."),
    }

    // 해시맵 순회
    for (key, value) in &scores {
        println!("{}: {}", key, value);
    }

    // 값 업데이트 (키가 존재하면 업데이트, 없으면 삽입)
    scores.insert(String::from("Blue"), 25);
    println!("Blue 팀 점수 업데이트: {:?}", scores);

    // `entry()` 메서드를 사용한 값 업데이트 (키가 없을 때만 삽입)
    scores.entry(String::from("Yellow")).or_insert(30); // Yellow는 이미 있으므로 변경 없음
    scores.entry(String::from("Red")).or_insert(40); // Red는 없으므로 40 삽입
    println!("entry() 사용 후 scores: {:?}", scores);

    // 기존 값을 기반으로 값 업데이트
    let text = "hello world wonderful world";
    let mut map = HashMap::new();

    for word in text.split_whitespace() {
        let count = map.entry(word).or_insert(0); // 키가 없으면 0을 삽입하고, 값에 대한 가변 참조 반환
        *count += 1; // 가변 참조를 역참조하여 값 증가
    }
    println!("단어 카운트: {:?}", map);

    // 학습 포인트: Rust의 컬렉션은 소유권과 빌림 규칙에 따라 안전하게 작동합니다.
    // `Vec`은 동적 배열, `String`은 가변 문자열, `HashMap`은 키-값 저장에 사용됩니다.
    // 문자열 인덱싱은 UTF-8 인코딩 특성 때문에 주의가 필요합니다.
}

// Rust Step 6: 트레잇 (Traits)
// 공유 동작을 정의하고 다형성을 구현하는 트레잇 학습

// 나쁜 예시: 모든 타입에 대해 동일한 기능을 개별적으로 구현하여 코드 중복을 초래하거나,
// 타입 간의 공통된 동작을 정의할 수 없어 유연성이 떨어짐.
// 좋은 예시: 트레잇을 사용하여 다양한 타입이 공유할 수 있는 동작을 정의하고,
// 제네릭과 함께 사용하여 코드 재사용성을 높이고 다형성을 구현.

// 학습 포인트: 트레잇은 Rust의 인터페이스와 유사하며, 공유 동작을 추상화하여 코드의 유연성과 재사용성을 높이는 강력한 메커니즘입니다.

// --- 1. 트레잇 정의 (Defining a Trait) ---
// 트레잇은 메서드 시그니처의 집합으로, 이 트레잇을 구현하는 모든 타입이 가져야 하는 동작을 정의합니다.
pub trait Summary {
    // 기본 구현(default implementation)을 제공할 수 있습니다.
    fn summarize_author(&self) -> String {
        String::from("(Read more from an unknown author)")
    }

    // 기본 구현이 없는 메서드
    fn summarize(&self) -> String;
}

// --- 2. 트레잇 구현 (Implementing a Trait) ---
// 특정 타입에 대해 트레잇의 메서드를 구현합니다.
pub struct NewsArticle {
    pub headline: String,
    pub location: String,
    pub author: String,
    pub content: String,
}

impl Summary for NewsArticle {
    fn summarize(&self) -> String {
        format!("{}, by {} ({})", self.headline, self.author, self.location)
    }

    fn summarize_author(&self) -> String {
        format!("@{}", self.author)
    }
}

pub struct Tweet {
    pub username: String,
    pub content: String,
    pub reply: bool,
    pub retweet: bool,
}

impl Summary for Tweet {
    fn summarize(&self) -> String {
        format!("{}: {}", self.username, self.content)
    }
}

// --- 3. 트레잇을 매개변수로 사용 (Trait as Parameters) ---
// 함수 매개변수에 트레잇 바운드(trait bound)를 사용하여 특정 트레잇을 구현하는 모든 타입을 받을 수 있습니다.
// 이는 다른 언어의 '인터페이스를 매개변수로 받는 것'과 유사한 다형성을 제공합니다.

// 3-1. `impl Trait` 구문 (간결한 문법)
pub fn notify_impl_trait(item: &impl Summary) { // Summary 트레잇을 구현하는 어떤 타입의 참조든 받을 수 있습니다.
    println!("속보! {}", item.summarize());
}

// 3-2. 트레잇 바운드 구문 (명시적인 문법)
// `pub fn notify_trait_bound<T: Summary>(item: &T)`
pub fn notify_trait_bound<T>(item: &T)
where
    T: Summary, // `where` 절을 사용하여 트레잇 바운드 명시
{
    println!("최신 뉴스! {}", item.summarize());
}

// 여러 트레잇 바운드 지정
// pub fn notify_multiple(item: &(impl Summary + Display)) { ... }
// pub fn notify_multiple<T: Summary + Display>(item: &T) { ... }
// pub fn notify_multiple<T>(item: &T) where T: Summary + Display { ... }

// --- 4. 트레잇을 반환 타입으로 사용 (Returning Trait) ---
// `impl Trait` 구문을 사용하여 트레잇을 구현하는 어떤 타입이든 반환할 수 있습니다.
// 단, 반환하는 모든 타입은 동일해야 합니다.
fn returns_summarizable() -> impl Summary {
    Tweet {
        username: String::from("horse_ebooks"),
        content: String::from("of course, as you probably already know, people"),
        reply: false,
        retweet: false,
    }
}

// --- 5. 트레잇의 기본 구현 오버라이딩 ---
// `NewsArticle`에서 `summarize_author`를 오버라이딩한 것을 확인할 수 있습니다.

fn main() {
    let tweet = Tweet {
        username: String::from("rustacean"),
        content: String::from("Rust 트레잇은 정말 강력해요!"),
        reply: false,
        retweet: false,
    };
    println!("트윗 요약: {}", tweet.summarize());
    println!("트윗 저자: {}", tweet.summarize_author());

    let article = NewsArticle {
        headline: String::from("펭귄, 남극에서 새로운 기술 발견!"),
        location: String::from("남극"),
        author: String::from("기자 박철수"),
        content: String::from("남극의 펭귄들이 놀라운 기술을 발견했다는 소식입니다..."),
    };
    println!("기사 요약: {}", article.summarize());
    println!("기사 저자: {}", article.summarize_author()); // 오버라이딩된 구현 사용

    // 트레잇을 매개변수로 사용하는 함수 호출
    notify_impl_trait(&tweet);
    notify_trait_bound(&article);

    // 트레잇을 반환하는 함수 호출
    let item = returns_summarizable();
    println!("반환된 아이템 요약: {}", item.summarize());

    // --- 6. 파생 트레잇 (Derive Traits) ---
    // Rust는 일부 트레잇을 `#[derive]` 속성을 사용하여 자동으로 구현해줍니다.
    // (예: `Debug`, `Clone`, `Copy`, `PartialEq`, `Eq`, `PartialOrd`, `Ord`, `Hash`)
    #[derive(Debug, PartialEq, Clone, Copy)] // Debug, PartialEq, Clone, Copy 트레잇 자동 구현
    struct Point {
        x: i32,
        y: i32,
    }

    let p1 = Point { x: 1, y: 2 };
    let p2 = Point { x: 1, y: 2 };
    let p3 = Point { x: 3, y: 4 };

    println!("p1: {:?}", p1);
    println!("p1 == p2: {}", p1 == p2); // PartialEq 덕분에 비교 가능
    let p1_clone = p1.clone(); // Clone 덕분에 복제 가능
    println!("p1_clone: {:?}", p1_clone);

    // --- 7. 고립 규칙 (Orphan Rule) ---
    // 트레잇을 구현할 때, 해당 트레잇이나 타입 중 적어도 하나는 현재 크레이트(crate)에서 정의되어야 합니다.
    // 즉, 외부 트레잇을 외부 타입에 구현할 수 없습니다. (예: `std::Vec`에 `Summary` 트레잇 구현 불가)
    // 이는 다른 크레이트들이 기존 타입에 새로운 동작을 정의하여 충돌하는 것을 방지합니다.

    // 학습 포인트: 트레잇은 Rust의 제네릭 프로그래밍, 다형성, 그리고 코드 재사용의 핵심입니다.
    // `impl Trait` 구문은 간결함을 제공하며, 트레잇 바운드는 더 명시적인 제약을 줍니다.
    // 기본 구현을 제공하여 중복 코드를 줄일 수도 있습니다.
}

// Rust Step 7: 제네릭과 생명 주기 (Generics & Lifetimes)
// 코드 재사용성과 타입 안전성을 높이는 제네릭 및 생명 주기 심화 학습

// 나쁜 예시: `any` 타입 대신 모든 타입에 대해 코드를 중복해서 작성하여 유지보수성 저해.
// 좋은 예시: 제네릭을 사용하여 여러 타입에서 동작하는 재사용 가능한 함수, 구조체, 열거형, 트레잇을 만들고,
// 생명 주기를 명시하여 참조의 유효성을 컴파일 타임에 보장.

// 학습 포인트: 제네릭은 코드의 중복을 줄이고 추상화를 높여주며, 생명 주기는 Rust의 메모리 안전성 규칙을 컴파일러에게 알려줍니다.

// --- 1. 제네릭 (Generics) ---
// 여러 타입에서 동작하는 코드 요소를 정의할 수 있게 해주는 기능.
// 함수, 구조체, 열거형, 메서드, 트레잇 정의에 사용됩니다.

// 1-1. 제네릭 함수
// `T`는 타입 매개변수 (Type Parameter)
fn largest<T: PartialOrd + Copy>(list: &[T]) -> T { // `PartialOrd`와 `Copy` 트레잇 바운드
    let mut largest = list[0];
    for &item in list.iter() {
        if item > largest {
            largest = item;
        }
    }
    largest
}

// `Clone` 대신 `Copy` 트레잇 바운드를 사용하는 것이 더 효율적일 수 있습니다.
// `Copy`는 비트 단위 복사, `Clone`은 깊은 복사 (힙 데이터까지 복사)
fn largest_clone<T: PartialOrd + Clone>(list: &[T]) -> T {
    let mut largest = list[0].clone();
    for item in list.iter() {
        if item.clone() > largest { // `item`은 참조이므로 `clone()`으로 역참조 후 복사
            largest = item.clone();
        }
    }
    largest
}

// 1-2. 제네릭 구조체
struct Point<T, U> {
    x: T,
    y: U,
}

impl<T, U> Point<T, U> {
    fn mixup<V, W>(self, other: Point<V, W>) -> Point<T, W> {
        Point {
            x: self.x,
            y: other.y,
        }
    }
}

// 1-3. 제네릭 열거형
// `Option<T>`와 `Result<T, E>`는 이미 제네릭 열거형입니다.
// enum Option<T> { Some(T), None, }
// enum Result<T, E> { Ok(T), Err(E), }

// --- 2. 생명 주기 (Lifetimes) ---
// Rust 컴파일러가 참조가 유효한 기간(스코프)을 알 수 있도록 하는 기능.
// Dangling References를 방지하여 메모리 안전성을 보장합니다.
// 모든 참조에는 생명 주기가 있습니다. 대부분은 컴파일러가 추론합니다.
// 함수 시그니처에서 생명 주기를 명시해야 하는 경우는 주로 "두 개 이상의 참조를 인자로 받고, 반환 값도 참조인 경우" 입니다.

// 2-1. 생명 주기 어노테이션 (`'a`)
// `'a`는 생명 주기 매개변수입니다. `'a`는 '어떤 생명 주기'를 의미합니다.
// 이 함수는 `x`와 `y`의 생명 주기 중 더 짧은 생명 주기 동안만 유효한 참조를 반환합니다.
fn longest<'a>(x: &'a str, y: &'a str) -> &'a str {
    if x.len() > y.len() {
        x
    } else {
        y
    }
}

// 2-2. 구조체 정의의 생명 주기 어노테이션
// 구조체가 참조를 저장할 경우, 해당 참조의 생명 주기를 명시해야 합니다.
struct ImportantExcerpt<'a> {
    part: &'a str,
}

// 2-3. 생명 주기 생략 규칙 (Lifetime Elision Rules)
// 컴파일러는 특정 패턴에서 생명 주기를 자동으로 추론합니다.
// - 입력 생명 주기 규칙:
//   - 각 입력 매개변수에 고유한 생명 주기 매개변수가 할당됩니다.
//   - 입력 매개변수가 하나뿐이면, 그 생명 주기가 모든 출력 생명 주기에 할당됩니다.
//   - 여러 입력 생명 주기 매개변수가 있지만 그 중 하나가 `&self` 또는 `&mut self`라면, `self`의 생명 주기가 모든 출력 생명 주기에 할당됩니다.
// - 위 규칙으로 생명 주기를 추론할 수 없을 때만 수동으로 어노테이션을 추가해야 합니다.

fn main() {
    // 제네릭 함수 사용
    let number_list = vec![34, 50, 25, 100, 65];
    let result_num = largest(&number_list);
    println!("가장 큰 숫자: {}", result_num);

    let char_list = vec!['y', 'm', 'a', 'q'];
    let result_char = largest(&char_list);
    println!("가장 큰 문자: {}", result_char);

    // 제네릭 구조체 사용
    let integer_and_float_point = Point { x: 5, y: 10.4 };
    let integer_point = Point { x: 5, y: 10 };
    println!("integer_point: x={}, y={}", integer_point.x, integer_point.y);

    let p1 = Point { x: 5, y: 10.4 };
    let p2 = Point { x: "Hello", y: 'c' };
    let p3 = p1.mixup(p2);
    println!("p3.x = {}, p3.y = {}", p3.x, p3.y);


    // 생명 주기 사용
    let string1 = String::from("Long string is long");
    {
        let string2 = String::from("xyz");
        let result = longest(string1.as_str(), string2.as_str());
        println!("더 긴 문자열: {}", result);
    }
    // string2는 이 스코프 밖에서 드롭되지만, longest가 반환한 result는 string1의 생명 주기를 따르므로 유효합니다.

    let novel = String::from("Call me Ishmael. Some years ago...");
    let first_sentence = novel.split('.').next().expect("점 '.'을 찾을 수 없습니다.");
    let i = ImportantExcerpt {
        part: first_sentence,
    };
    println!("중요 발췌문: {}", i.part);

    // 학습 포인트: 제네릭과 생명 주기는 Rust의 안전하고 고성능의 코드를 작성하는 데 필수적인 개념입니다.
    // 제네릭은 코드의 추상화와 재사용성을 높여주며, 생명 주기는 컴파일 타임에 메모리 안전성을 보장합니다.
    // 이 두 가지를 올바르게 사용하는 것은 Rust의 진정한 강점을 활용하는 방법입니다.
}

// Rust Step 8: 모듈 시스템 (Modules)
// 코드 조직화를 위한 모듈, 크레이트, 패키지 시스템 이해

// 나쁜 예시: 모든 코드를 하나의 파일에 작성하여 코드량이 많아지고 재사용성 및 유지보수성 저해.
// 좋은 예시: 모듈 시스템을 사용하여 코드를 논리적으로 분리하고, 공개/비공개 범위를 명확히 하며,
// Cargo 패키지 시스템을 통해 의존성을 효율적으로 관리.

// 학습 포인트: Rust의 모듈 시스템은 코드의 구조화, 재사용성, 그리고 접근 제어를 위한 핵심 기능입니다.

// --- 1. 크레이트 (Crates) ---
// Rust에서 컴파일 단위 (코드의 가장 작은 단위).
// - **바이너리 크레이트 (Binary Crate)**: 실행 가능한 프로그램을 생성합니다. `main` 함수를 포함.
// - **라이브러리 크레이트 (Library Crate)**: 다른 프로그램에서 사용할 수 있는 라이브러리를 생성합니다. `main` 함수 없음.
// `Cargo.toml` 파일의 `[lib]` 또는 `[bin]` 섹션에 정의됩니다.

// --- 2. 패키지 (Packages) ---
// 하나 이상의 크레이트(라이브러리/바이너리)와 `Cargo.toml` 파일로 구성됩니다.
// `Cargo.toml`은 패키지의 메타데이터와 의존성 정보를 포함합니다.

// --- 3. 모듈 (Modules) ---
// 크레이트 내부에서 코드를 조직화하는 단위.
// - `mod` 키워드를 사용하여 정의.
// - 파일 시스템 구조를 따라갈 수도 있습니다 (예: `src/lib.rs`는 루트 모듈).
// - `pub` 키워드를 사용하여 외부로 공개. 기본적으로 모든 것은 비공개.

// --- 모듈 예시 (main.rs 또는 lib.rs 내에서) ---

// `front_of_house`라는 모듈 정의
mod front_of_house {
    pub mod hosting { // `hosting` 모듈은 `front_of_house` 외부에서 `pub`으로 접근 가능
        pub fn add_to_waitlist() { // `add_to_waitlist` 함수는 `hosting` 외부에서 `pub`으로 접근 가능
            println!("테이블 대기 목록에 추가됨.");
            seat_at_table(); // 동일 모듈 내 함수 호출
        }

        fn seat_at_table() { // 이 함수는 `hosting` 모듈 내부에서만 접근 가능
            println!("손님을 테이블에 앉힘.");
        }
    }

    mod serving { // `serving` 모듈은 `front_of_house` 내부에서만 접근 가능
        fn take_order() {
            println!("주문 받음.");
        }
        fn serve_order() {
            println!("주문 서빙.");
        }
        fn take_payment() {
            println!("결제 받음.");
        }
    }
}

// --- `use` 키워드 ---
// 모듈 경로를 짧게 만들어 코드 가독성을 높입니다.
// `use`는 경로를 스코프로 가져오는 것이지, 아이템을 공개(public)하는 것이 아닙니다.
use crate::front_of_house::hosting; // `crate`는 현재 크레이트의 루트를 의미.

fn main() {
    println!("--- Rust 모듈 시스템 ---");

    // `front_of_house` 모듈의 `hosting` 모듈에 있는 `add_to_waitlist` 함수 호출
    // `use` 키워드를 사용했으므로 `hosting::add_to_waitlist()`로 호출 가능
    hosting::add_to_waitlist();

    // `use` 키워드 없이 전체 경로를 사용하여 호출
    crate::front_of_house::hosting::add_to_waitlist();

    // --- `super` 키워드 ---
    // 현재 모듈의 부모 모듈을 참조합니다.

    // --- `pub use` (Re-exporting) ---
    // `pub use`는 아이템을 현재 스코프에 가져오고, 동시에 다른 코드도 이 아이템을 가져갈 수 있도록 공개합니다.
    pub mod customer_service {
        // `hosting` 모듈을 `customer_service` 모듈의 일부로 가져오고, 외부로도 공개합니다.
        pub use crate::front_of_house::hosting;

        pub fn serve_customer() {
            hosting::add_to_waitlist(); // `use` 덕분에 짧은 경로로 호출
            println!("고객 응대 완료.");
        }
    }
    customer_service::serve_customer();

    // --- 파일 시스템으로 모듈 분리 ---
    // 모듈이 커지면 별도의 파일로 분리하는 것이 일반적입니다.
    // - `src/main.rs` (또는 `src/lib.rs`)는 크레이트 루트입니다.
    // - `mod garden;`을 `src/main.rs`에 선언하면 `garden` 모듈을 정의하고
    //   `src/garden.rs` 또는 `src/garden/mod.rs` 파일을 찾습니다.

    // 예시: `src/garden.rs` 파일이 있다고 가정
    // pub mod garden {
    //     pub struct Vegetable {
    //         pub name: String,
    //         id: i32,
    //     }
    //     impl Vegetable {
    //         pub fn new(name: String) -> Vegetable {
    //             Vegetable { name, id: 1 }
    //         }
    //     }
    // }
    //
    // fn main() {
    //     let plant = garden::Vegetable::new(String::from("당근"));
    //     println!("이 식물의 이름은 {}입니다.", plant.name);
    //     // println!("이 식물의 ID는 {}입니다.", plant.id); // Error: `id`는 비공개 필드입니다.
    // }

    // --- `pub(crate)` 와 `pub(super)` ---
    // 더 세밀한 접근 제어를 위해 사용됩니다.
    // `pub(crate)`: 현재 크레이트 내에서만 공개.
    // `pub(super)`: 부모 모듈 내에서만 공개.

    // --- Cargo.toml과 의존성 관리 ---
    // `Cargo.toml` 파일의 `[dependencies]` 섹션에 외부 크레이트를 추가합니다.
    // [dependencies]
    // rand = "0.8.5"
    //
    // 이후 `use rand::Rng;` 와 같이 사용 가능합니다.
    use rand::Rng;
    let secret_number = rand::thread_rng().gen_range(1..=100);
    println!("생성된 비밀 숫자 (rand 크레이트 사용): {}", secret_number);


    // 학습 포인트: Rust의 모듈 시스템은 코드를 체계적으로 정리하고, 공개/비공개 범위를 명확히 하여
    // 대규모 프로젝트의 관리와 협업을 용이하게 합니다.
    // `pub`과 `use` 키워드를 적절히 사용하여 접근성과 가독성을 높이는 것이 중요합니다.
}

// Rust Step 9: 테스트와 문서화 (Testing & Documentation)
// 단위 테스트, 통합 테스트 작성 및 `cargo doc`을 활용한 문서화

// 나쁜 예시: 테스트 코드를 작성하지 않거나, 문서화를 소홀히 하여 코드 변경 시 버그 발생 가능성 높고,
// 다른 개발자가 코드를 이해하고 사용하기 어려움.
// 좋은 예시: 견고한 테스트 스위트를 구축하여 코드의 정확성을 보장하고,
// Rust의 문서화 도구를 활용하여 코드를 쉽게 이해하고 사용할 수 있도록 함.

// 학습 포인트: 테스트와 문서화는 소프트웨어 품질을 보장하고 개발 효율성을 높이는 데 필수적입니다.

// --- 1. 테스트 (Testing) ---
// Rust는 `cargo test` 명령어를 사용하여 테스트를 실행합니다.

// 1-1. 단위 테스트 (Unit Tests)
// - 개별적인, 격리된 코드 단위를 테스트합니다.
// - 일반적으로 테스트 대상 코드와 동일한 파일에 `#[cfg(test)]` 속성을 가진 모듈 내부에 작성합니다.
// - `assert!`, `assert_eq!`, `assert_ne!` 등의 매크로를 사용하여 예상 결과와 실제 결과를 비교합니다.

pub fn add_two(a: i32) -> i32 {
    a + 2
}

#[cfg(test)] // 이 모듈은 `cargo test`를 실행할 때만 컴파일됩니다.
mod tests {
    use super::*; // 부모 모듈의 아이템(예: add_two 함수)을 현재 스코프로 가져옵니다.

    #[test] // 이 함수가 테스트 함수임을 나타냅니다.
    fn it_adds_two() {
        assert_eq!(4, add_two(2)); // `assert_eq!` 매크로 사용
    }

    #[test]
    fn another_test() {
        assert_ne!(5, add_two(2)); // `assert_ne!` 매크로 사용
    }

    #[test]
    #[should_panic(expected = "값을 0으로 나눌 수 없습니다.")] // 패닉이 발생하는 테스트
    fn test_divide_by_zero_panic() {
        divide(10, 0);
    }

    #[test]
    #[ignore] // `cargo test -- --ignored`로만 실행
    fn expensive_test() {
        // 이 테스트는 실행 시간이 오래 걸리므로 기본적으로 무시합니다.
        println!("매우 비싼 테스트 실행!");
        assert!(true);
    }
}

// `panic!`이 발생하는 함수
fn divide(numerator: i32, denominator: i32) -> i32 {
    if denominator == 0 {
        panic!("값을 0으로 나눌 수 없습니다.");
    }
    numerator / denominator
}

