// 5. 인터페이스 확장 (Extending Interfaces)
interface BasicPerson {
    name: string;
    age: number;
}

interface Employee extends BasicPerson { // BasicPerson 인터페이스 확장
    employeeId: string;
    department: string;
}

const employee: Employee = {
    name: "Jane Doe",
    age: 40,
    employeeId: "EMP001",
