// 학습 포인트: 인터페이스는 코드의 구조를 명확히 하고, 타입 안정성을 확보하며, 다른 개발자와의 협업을 용이하게 합니다.
// 특히 객체의 형태를 미리 약속해야 하는 상황(API 응답, 데이터 모델 등)에서 매우 유용합니다.

// TypeScript 타입 별칭 (Type Aliases)
// 복잡한 타입 정의를 위한 타입 별칭 활용 및 인터페이스와의 차이점

// 나쁜 예시: 복잡하고 반복적인 타입을 매번 길게 작성하여 코드 가독성을 해치거나, 재사용성을 떨어뜨립니다.
// 좋은 예시: 타입 별칭을 사용하여 복잡한 타입을 간결하게 재정의하고, 코드의 가독성 및 재사용성을 높입니다.

// --- 1. 타입 별칭의 기본 사용 ---
// 원시 타입, 유니온 타입, 인터섹션 타입, 튜플, 함수 등 모든 타입에 별칭을 부여할 수 있습니다.
type MyString = string;
let text: MyString = "안녕하세요";
console.log(`MyString 타입 변수: ${text}`);

type MyNumber = number;
let count: MyNumber = 100;
console.log(`MyNumber 타입 변수: ${count}`);

// --- 2. 유니온 타입 (Union Types)에 별칭 사용 ---
// 여러 타입 중 하나를 가질 수 있음을 나타냅니다.
type StringOrNumber = string | number;
let value1: StringOrNumber = "hello";
let value2: StringOrNumber = 123;
// let value3: StringOrNumber = true; // Error: Type 'boolean' is not assignable to type 'StringOrNumber'.

function printId(id: StringOrNumber) {
    console.log(`ID: ${id}`);
}
printId("abc");
printId(123);

// --- 3. 객체 타입에 별칭 사용 ---
// 인터페이스와 유사하게 객체의 구조를 정의할 수 있습니다.
type Point = {
    x: number;
    y: number;
};

function printCoord(pt: Point) {
    console.log(`X 좌표: ${pt.x}, Y 좌표: ${pt.y}`);
}
printCoord({ x: 10, y: 20 });

// --- 4. 인터섹션 타입 (Intersection Types)에 별칭 사용 ---
// 여러 타입을 모두 만족하는 타입을 생성합니다.
type Person = {
    name: string;
    age: number;
};

type Employee = {
    employeeId: string;
    department: string;
};

type FullEmployee = Person & Employee; // Person과 Employee의 모든 속성을 포함

const fullEmployee: FullEmployee = {
    name: "홍길동",
    age: 30,
    employeeId: "E123",
    department: "개발"
};
console.log(`전체 직원 정보: 이름 - ${fullEmployee.name}, 부서 - ${fullEmployee.department}`);


// --- 5. 함수 타입에 별칭 사용 ---
type GreetFunction = (name: string) => string;

const sayHello: GreetFunction = (name) => `Hello, ${name}!`;
console.log(sayHello("TypeScript"));

// --- 6. 인터페이스와 타입 별칭의 차이점 ---

// 1) 확장 (Extends)
// 인터페이스는 `extends` 키워드를 사용하여 확장할 수 있습니다.
interface IBase {
    id: number;
}
interface IExtended extends IBase {
    name: string;
}

// 타입 별칭은 인터섹션(&)을 사용하여 확장과 유사한 효과를 낼 수 있습니다.
type TBase = {
    id: number;
};
type TExtended = TBase & { name: string };


// 2) 구현 (Implements)
// 클래스는 인터페이스를 `implements` 할 수 있습니다.
interface Shape {
    draw(): void;
}
class Circle implements Shape {
    draw() { console.log("원을 그립니다."); }
}

// 타입 별칭은 `implements` 할 수 없습니다.
// class Square implements TBase { } // Error: A class can only implement an interface or a class with a 'constructor' member.


// 3) 선언적 병합 (Declaration Merging)
// 인터페이스는 동일한 이름으로 여러 번 선언되어도 자동으로 병합됩니다.
interface MergedInterface {
    a: number;
}
interface MergedInterface {
    b: string;
}
const merged: MergedInterface = { a: 1, b: "hi" }; // { a: number; b: string; }

// 타입 별칭은 동일한 이름으로 여러 번 선언할 수 없으며, 병합되지 않습니다.
// type MergedType { a: number; }
// type MergedType { b: string; } // Error: Duplicate identifier 'MergedType'.


// 4) 원시 타입, 유니온 타입 등 표현
// 타입 별칭은 원시 타입, 유니온 타입, 튜플 등 모든 타입을 표현할 수 있습니다.
type MyStringOrNumber = string | number;
type MyTuple = [string, number];

// 인터페이스는 객체 타입만 표현할 수 있습니다.


// --- 결론 ---
// - 복잡한 객체 구조를 정의하고 클래스와 함께 사용할 때는 **인터페이스**가 더 적합합니다 (확장 및 구현 용이).
// - 유니온 타입, 인터섹션 타입, 원시 타입, 튜플 등 객체 외의 다양한 타입을 조합할 때는 **타입 별칭**이 더 유용합니다.
// - 대부분의 경우 두 가지 모두 사용할 수 있지만, 프로젝트의 컨벤션과 특정 사용 사례에 따라 선택하는 것이 좋습니다.

// 학습 포인트: 타입 별칭과 인터페이스는 TypeScript 코드의 가독성과 유지보수성을 높이는 데 핵심적인 역할을 합니다.
// 각자의 특징과 장단점을 이해하고 적절한 상황에 맞는 것을 선택하는 연습이 중요합니다.

// TypeScript 클래스 (Class)
// TypeScript 클래스의 접근 제어자, 상속, 인터페이스 구현

// 나쁜 예시: 모든 클래스 멤버를 public으로 선언하여 외부에서 무분별하게 접근하고 수정할 수 있게 만듭니다.
// 좋은 예시: `public`, `private`, `protected`, `readonly`와 같은 접근 제어자를 사용하여 캡슐화를 강화하고, 상속과 인터페이스 구현으로 재사용성과 확장성 있는 코드를 작성합니다.

// --- 1. 클래스 기본 ---
class Greeter {
    // 속성 (Property)
    greeting: string;

    // 생성자 (Constructor)
    constructor(message: string) {
        this.greeting = message;
    }

    // 메서드 (Method)
    greet() {
        return "Hello, " + this.greeting;
    }
}

let greeter = new Greeter("world");
console.log(greeter.greet());

// --- 2. 상속 (Inheritance) ---
class Animal {
    name: string;
    constructor(theName: string) { this.name = theName; }
    move(distanceInMeters: number = 0) {
        console.log(`${this.name}가 ${distanceInMeters}m 이동했습니다.`);
    }
}

class Snake extends Animal {
    constructor(name: string) { super(name); } // 부모 클래스 생성자 호출
    move(distanceInMeters = 5) {
        console.log("꿈틀거립니다...");
        super.move(distanceInMeters); // 부모 클래스의 메서드 호출
    }
}

class Horse extends Animal {
    constructor(name: string) { super(name); }
    move(distanceInMeters = 45) {
        console.log("질주합니다...");
        super.move(distanceInMeters);
    }
}

let sam = new Snake("샘 뱀");
let tom: Animal = new Horse("톰 말"); // 다형성 (Polymorphism)

sam.move();
tom.move(34);


// --- 3. 접근 제어자 (Access Modifiers) ---
// public (기본값): 모든 곳에서 접근 가능
// private: 클래스 내부에서만 접근 가능
// protected: 클래스 내부 및 파생 클래스(자식 클래스) 내부에서 접근 가능
// readonly: 생성 시 또는 선언 시에만 값을 할당할 수 있으며, 이후에는 변경 불가

class Person {
    public name: string; // public (기본값)
    private age: number; // private
    protected gender: string; // protected
    readonly birthYear: number; // readonly

    constructor(name: string, age: number, gender: string, birthYear: number) {
        this.name = name;
        this.age = age;
        this.gender = gender;
        this.birthYear = birthYear;
    }

    public getAge(): number { // public 메서드
        return this.age;
    }

    protected getGender(): string { // protected 메서드
        return this.gender;
    }

    // private setAge(newAge: number): void { // private 메서드 (클래스 내부에서만 사용)
    //     this.age = newAge;
    // }
}

class Employee extends Person {
    private employeeId: string;

    constructor(name: string, age: number, gender: string, birthYear: number, employeeId: string) {
        super(name, age, gender, birthYear); // 부모 클래스 생성자 호출
        this.employeeId = employeeId;
    }

    public getEmployeeInfo(): string {
        // console.log(this.age); // Error: Property 'age' is private and only accessible within class 'Person'.
        console.log(`성별 (protected): ${this.gender}`); // protected 멤버 접근 가능
        return `${this.name} (ID: ${this.employeeId}, 나이: ${this.getAge()}, 성별: ${this.getGender()})`;
    }
}

let alice = new Person("Alice", 30, "Female", 1993);
console.log(alice.name);
// console.log(alice.age); // Error: Property 'age' is private
// console.log(alice.gender); // Error: Property 'gender' is protected
// alice.birthYear = 1994; // Error: Cannot assign to 'birthYear' because it is a read-only property.

let bob = new Employee("Bob", 35, "Male", 1988, "EMP001");
console.log(bob.name);
console.log(bob.getAge());
console.log(bob.getEmployeeInfo());


// --- 4. 매개변수 속성 (Parameter Properties) ---
// 생성자의 매개변수에 접근 제어자를 붙이면 해당 이름의 속성으로 자동 선언됩니다.
class Car {
    constructor(public brand: string, public readonly year: number, private _mileage: number) {}

    get mileage(): number { // getter
        return this._mileage;
    }

    set mileage(value: number) { // setter
        if (value < this._mileage) {
            throw new Error("주행 거리는 줄어들 수 없습니다.");
        }
        this._mileage = value;
    }
}

let myCar = new Car("Hyundai", 2020, 50000);
console.log(myCar.brand);
console.log(myCar.year);
console.log(myCar.mileage);
myCar.mileage = 55000;
console.log(myCar.mileage);
// myCar.year = 2021; // Error: Cannot assign to 'year' because it is a read-only property.


// --- 5. 추상 클래스 (Abstract Classes) ---
// 추상 클래스는 다른 클래스들이 파생될 수 있는 기본 클래스이며, 직접 인스턴스화할 수 없습니다.
// 추상 메서드를 포함할 수 있으며, 파생 클래스에서 반드시 구현되어야 합니다.
abstract class Department {
    constructor(public name: string) {}

    printName(): void {
        console.log("Department name: " + this.name);
    }

    abstract printMeeting(): void; // 추상 메서드는 구현부가 없습니다.
}

class AccountingDepartment extends Department {
    constructor() {
        super("회계 부서"); // 파생 클래스의 생성자에서 super() 호출 필수
    }

    printMeeting(): void { // 추상 메서드 구현
        console.log("회계 부서는 매주 월요일 오전에 회의를 진행합니다.");
    }

    generateReports(): void {
        console.log("회계 보고서를 생성합니다.");
    }
}

// let department = new Department(); // Error: Cannot create an instance of an abstract class.
let accounting = new AccountingDepartment();
accounting.printName();
accounting.printMeeting();
accounting.generateReports();


// --- 6. 인터페이스 구현 (Implementing Interfaces) ---
// 클래스는 하나 또는 여러 개의 인터페이스를 구현할 수 있습니다.
interface GreeterInterface {
    greeting: string;
    sayHello(): string;
}

class MyGreeter implements GreeterInterface {
    greeting: string;
    constructor(message: string) {
        this.greeting = message;
    }
    sayHello(): string {
        return "안녕하세요, " + this.greeting;
    }
}

let customGreeter = new MyGreeter("TypeScript!");
console.log(customGreeter.sayHello());

// 학습 포인트: TypeScript의 클래스는 ES6 클래스 문법에 타입과 접근 제어자 등 추가 기능을 제공하여,
// 더 견고하고 객체 지향적인 코드 작성을 가능하게 합니다.

// TypeScript 함수 (Functions)
// 함수 오버로딩, 선택적 매개변수, 기본 매개변수, Rest 매개변수

// 나쁜 예시: `any` 타입을 매개변수나 반환 타입으로 사용하거나, 함수의 시그니처를 명확하게 정의하지 않아 호출 시 예상치 못한 동작을 유발.
// 좋은 예시: 함수의 매개변수와 반환 타입, 오버로딩 등을 명확하게 정의하여 타입 안정성을 확보하고 가독성을 높임.

// --- 1. 기본 함수 정의 ---
// 매개변수와 반환 값에 타입을 명시합니다.
function add(x: number, y: number): number {
    return x + y;
}
console.log(`add(10, 20): ${add(10, 20)}`);

// 함수 표현식 (Function Expression)
let myAdd: (x: number, y: number) => number = function(x: number, y: number): number {
    return x + y;
};
console.log(`myAdd(5, 7): ${myAdd(5, 7)}`);

// --- 2. 선택적 매개변수 (Optional Parameters) ---
// 매개변수 이름 뒤에 `?`를 붙여 선택적 매개변수로 만듭니다.
// 선택적 매개변수는 항상 필수 매개변수 뒤에 와야 합니다.
function buildName(firstName: string, lastName?: string): string {
    if (lastName) {
        return firstName + " " + lastName;
    } else {
        return firstName;
    }
}
let result1 = buildName("Bob"); // Bob
let result2 = buildName("Bob", "Adams"); // Bob Adams
// let result3 = buildName("Bob", "Adams", "Sr."); // Error: Expected 2 arguments, but got 3.
console.log(`buildName("Bob"): ${result1}`);
console.log(`buildName("Bob", "Adams"): ${result2}`);


// --- 3. 기본 매개변수 (Default Parameters) ---
// 매개변수에 기본값을 할당하여 선택적 매개변수처럼 동작하게 합니다.
// 기본값이 있는 매개변수는 필수 매개변수 뒤에 오거나, 필수 매개변수 앞에 올 수도 있지만 이때는 `undefined`를 전달해야 합니다.
function buildNameWithDefault(firstName: string, lastName: string = "Smith"): string {
    return firstName + " " + lastName;
}
let result4 = buildNameWithDefault("Bob"); // Bob Smith
let result5 = buildNameWithDefault("Bob", "Adams"); // Bob Adams
let result6 = buildNameWithDefault("Bob", undefined); // Bob Smith
// let result7 = buildNameWithDefault("Bob", "Adams", "Sr."); // Error: Expected 2 arguments, but got 3.
console.log(`buildNameWithDefault("Bob"): ${result4}`);
console.log(`buildNameWithDefault("Bob", "Adams"): ${result5}`);
console.log(`buildNameWithDefault("Bob", undefined): ${result6}`);


// --- 4. Rest 매개변수 (Rest Parameters) ---
// 매개변수의 개수를 알 수 없을 때 배열 형태로 매개변수를 받습니다.
function sumAllNumbers(firstNum: number, ...restOfNumbers: number[]): number {
    let total = firstNum;
    for (let i = 0; i < restOfNumbers.length; i++) {
        total += restOfNumbers[i];
    }
    return total;
}
let sum1 = sumAllNumbers(1, 2, 3, 4, 5); // 첫 번째 인자는 firstNum에 할당, 나머지는 restOfNumbers 배열에 할당
console.log(`sumAllNumbers(1, 2, 3, 4, 5): ${sum1}`);

let sum2 = sumAllNumbers(10);
console.log(`sumAllNumbers(10): ${sum2}`);


// --- 5. 함수 오버로딩 (Function Overloads) ---
// 하나의 함수에 대해 여러 개의 시그니처를 정의하여 다양한 타입의 인자를 처리할 수 있게 합니다.
// 오버로드 시그니처는 구현 시그니처 앞에 와야 하며, 실제 구현은 가장 일반적인 타입으로 작성해야 합니다.

function reverse(string: string): string;
function reverse(array: any[]): any[];
function reverse(value: string | any[]): string | any[] {
    if (typeof value === "string") {
        return value.split("").reverse().join("");
    } else {
        return value.slice().reverse(); // 원본 배열을 수정하지 않도록 slice() 사용
    }
}

console.log(`reverse("hello"): ${reverse("hello")}`);
console.log(`reverse([1, 2, 3]): ${reverse([1, 2, 3])}`);
// console.log(reverse(123)); // Error: No overload matches this call.

// 오버로딩 사용 예시 (객체 생성)
interface Coordinate {
    x: number;
    y: number;
}

function makePoint(x: number, y: number): Coordinate;
function makePoint(coord: Coordinate): Coordinate;
function makePoint(xOrCoord: number | Coordinate, y?: number): Coordinate {
    if (typeof xOrCoord === 'number' && typeof y === 'number') {
        return { x: xOrCoord, y: y };
    } else if (typeof xOrCoord === 'object' && xOrCoord !== null && 'x' in xOrCoord && 'y' in xOrCoord) {
        return { x: xOrCoord.x, y: xOrCoord.y };
    }
    throw new Error("Invalid arguments for makePoint");
}

let point1 = makePoint(10, 20);
let point2 = makePoint({ x: 30, y: 40 });
console.log(`makePoint(10, 20): X=${point1.x}, Y=${point1.y}`);
console.log(`makePoint({ x: 30, y: 40 }): X=${point2.x}, Y=${point2.y}`);


// 학습 포인트: TypeScript의 함수 기능들을 활용하여 함수의 의도를 명확히 하고,
// 다양한 사용 케이스를 타입 안전하게 처리할 수 있습니다.
// 특히 오버로딩은 여러 인자 타입에 대응하는 유연한 함수를 만들 때 유용합니다.

// TypeScript 제네릭 (Generics)
// 재사용 가능한 컴포넌트 생성을 위한 제네릭 활용

// 나쁜 예시: `any` 타입을 사용하여 여러 타입의 데이터를 처리하려 하여 타입 안전성을 잃거나,
// 각 타입별로 유사한 코드를 반복하여 작성하여 코드 중복을 초래합니다.
// 좋은 예시: 제네릭을 사용하여 여러 타입에서 동작하는 재사용 가능한 함수, 인터페이스, 클래스를 만들고,
// 동시에 타입 안전성도 유지하여 코드 중복을 줄이고 유연성을 높입니다.

// --- 1. 제네릭 함수 (Generic Functions) ---
// 함수에 타입 변수를 추가하여 다양한 타입에서 동작하도록 합니다.
function identity<T>(arg: T): T {
    return arg;
}

let output1 = identity<string>("myString"); // 명시적으로 string 타입을 지정
let output2 = identity("myString");       // 타입 추론으로 string 타입이 됨
let output3 = identity(123);              // 타입 추론으로 number 타입이 됨

console.log(`identity("myString"): ${output1} (${typeof output1})`);
console.log(`identity(123): ${output3} (${typeof output3})`);


// 여러 타입 변수 사용
function pair<T, U>(arg1: T, arg2: U): [T, U] {
    return [arg1, arg2];
}
let myPair = pair("hello", 123);
console.log(`pair("hello", 123): [${myPair[0]}, ${myPair[1]}]`);


// --- 2. 제네릭 인터페이스 (Generic Interfaces) ---
// 인터페이스에 타입 변수를 추가하여 다양한 타입의 객체에 대한 계약을 정의합니다.
interface GenericIdentityFn<T> {
    (arg: T): T;
}

let myIdentity: GenericIdentityFn<number> = identity;
console.log(`myIdentity(456): ${myIdentity(456)}`);


interface Box<T> {
    value: T;
}

let stringBox: Box<string> = { value: "문자열" };
let numberBox: Box<number> = { value: 123 };
console.log(`stringBox: ${stringBox.value}`);
console.log(`numberBox: ${numberBox.value}`);


// --- 3. 제네릭 클래스 (Generic Classes) ---
// 클래스에 타입 변수를 추가하여 다양한 타입의 데이터를 다루는 클래스를 만듭니다.
class GenericNumber<T> {
    zeroValue: T;
    add: (x: T, y: T) => T;

    constructor(zero: T, addFunction: (x: T, y: T) => T) {
        this.zeroValue = zero;
        this.add = addFunction;
    }
}

let myGenericNumber = new GenericNumber<number>(0, (x, y) => x + y);
console.log(`myGenericNumber.add(10, 20): ${myGenericNumber.add(10, 20)}`);

let stringCombiner = new GenericNumber<string>("", (x, y) => x + y);
console.log(`stringCombiner.add("Hello, ", "Generics!"): ${stringCombiner.add("Hello, ", "Generics!")}`);


// --- 4. 제네릭 제약 조건 (Generic Constraints) ---
// 모든 타입에서 동작하는 것이 아니라, 특정 속성이나 메서드를 가진 타입으로 제한할 때 사용합니다.
interface Lengthwise {
    length: number;
}

function loggingIdentity<T extends Lengthwise>(arg: T): T {
    console.log(`길이: ${arg.length}`); // now we know it has a .length property
    return arg;
}

// loggingIdentity(3); // Error: Argument of type 'number' is not assignable to parameter of type 'Lengthwise'.
loggingIdentity({ length: 10, value: 3 }); // { length: 10, value: 3 }
loggingIdentity("hello world"); // string은 length 속성을 가짐
loggingIdentity([1, 2, 3]); // 배열은 length 속성을 가짐

// 키 제약 조건 (keyof)
function getProperty<T, K extends keyof T>(obj: T, key: K): T[K] {
    return obj[key];
}

let user = { id: 1, name: "Alice", email: "alice@example.com" };
let id = getProperty(user, "id");
let name = getProperty(user, "name");
// let address = getProperty(user, "address"); // Error: Argument of type '"address"' is not assignable to parameter of type '"id" | "name" | "email"'.
console.log(`user.id: ${id}`);
console.log(`user.name: ${name}`);


// 학습 포인트: 제네릭은 코드의 재사용성을 높이고, 타입 추론을 통해 타입 안전성을 유지하며,
// 유연하고 확장 가능한 컴포넌트를 설계하는 데 필수적인 기능입니다.
// 복잡한 타입 시스템을 다룰 때 강력한 도구가 됩니다.

// TypeScript 열거형 (Enums)
// 숫자 또는 문자열 기반의 열거형 정의 및 활용

// 나쁜 예시: 하드코딩된 '마법의 문자열/숫자'를 사용하여 코드의 의미를 파악하기 어렵게 만들거나, 오타로 인한 오류를 발생시킵니다.
// 좋은 예시: 열거형을 사용하여 관련 값들의 집합에 의미 있는 이름을 부여하고, 코드의 가독성 및 유지보수성을 높입니다.

// --- 1. 숫자 열거형 (Numeric Enums) ---
// 기본적으로 0부터 시작하여 1씩 증가합니다.
enum Direction {
    Up,      // 0
    Down,    // 1
    Left,    // 2
    Right    // 3
}

let userDirection: Direction = Direction.Up;
console.log(`사용자 방향: ${userDirection} (${Direction.Up})`); // 0

// 값을 수동으로 지정할 수도 있습니다.
enum StatusCode {
    NotFound = 404,
    Success = 200,
    Accepted = 202,
    BadRequest = 400
}

let responseStatus: StatusCode = StatusCode.Success;
console.log(`응답 상태: ${responseStatus} (${StatusCode.Success})`); // 200

// 역방향 매핑 (Reverse Mapping): 숫자 열거형은 숫자 값을 통해 열거형 멤버의 이름을 얻을 수 있습니다.
let successCode: number = 200;
console.log(`200의 열거형 이름: ${StatusCode[successCode]}`); // Success


// --- 2. 문자열 열거형 (String Enums) ---
// 모든 멤버에 문자열 리터럴로 초기화해야 합니다.
// 숫자 열거형에 비해 가독성이 좋고 디버깅에 유리합니다.
enum UserRole {
    Admin = "ADMIN",
    Editor = "EDITOR",
    Viewer = "VIEWER"
}

let currentUserRole: UserRole = UserRole.Admin;
console.log(`현재 사용자 역할: ${currentUserRole}`); // ADMIN

function checkPermissions(role: UserRole): void {
    if (role === UserRole.Admin) {
        console.log("관리자 권한이 있습니다.");
    } else {
        console.log("일반 사용자 권한입니다.");
    }
}
checkPermissions(currentUserRole);
checkPermissions(UserRole.Editor);

// 문자열 열거형은 역방향 매핑을 지원하지 않습니다.
