console.log(`사용자 이메일: ${userProfile.email}`);
// userProfile.age = 30; // Error: Property 'age' does not exist on type 'UserProfile'.

// 이중 단언 (Double Assertion)
// `any`를 거쳐 다른 타입으로 단언하는 것은 강력하지만, 주의해서 사용해야 합니다.
