    <h2>사용자 정보</h2>
    <p>{{ greet() }}</p>
    <input type="text" v-model="person.name" placeholder="이름">
    <input type="number" v-model.number="person.age" placeholder="나이">
    <p>이름: {{ person.name }}, 나이: {{ person.age }}</p>

    <br>
    <p>Vue.js는 데이터를 변경하면 자동으로 화면이 업데이트됩니다. 직접 DOM을 조작할 필요가 없습니다.</p>
</div>
*/

// Vue2 컴포넌트 기본
// 컴포넌트 생성 및 등록, props를 이용한 데이터 전달

// 나쁜 예시: 모든 UI를 하나의 Vue 인스턴스 내에서 관리하여 코드 재사용성이 떨어지고, 유지보수가 어려움.
// 좋은 예시: UI를 재사용 가능한 작은 컴포넌트로 분리하고, props를 통해 데이터를 명확하게 전달하여 컴포넌트 간의 결합도를 낮춤.

// --- 1. 전역 컴포넌트 등록 ---
// 모든 Vue 인스턴스/컴포넌트에서 사용 가능
Vue.component('my-button', {
    // 템플릿은 컴포넌트의 UI 구조를 정의합니다.
    template: `
        <button @click="handleClick">
            {{ text }} ({{ clickCount }})
        </button>
    `,
    // props는 부모 컴포넌트로부터 데이터를 전달받는 속성입니다.
    props: {
        text: {
            type: String,
            default: '클릭하세요'
        }
    },
    // 컴포넌트의 데이터는 함수로 정의하여 각 인스턴스가 독립적인 데이터 객체를 가지도록 합니다.
    data() {
        return {
            clickCount: 0
        };
    },
    methods: {
        handleClick() {
            this.clickCount++;
            // 부모 컴포넌트에 이벤트를 발생시켜 알립니다. (추후 Step3에서 상세 학습)
            this.$emit('button-clicked', this.clickCount);
        }
    }
});

// --- 2. 지역 컴포넌트 등록 ---
// 특정 Vue 인스턴스/컴포넌트에서만 사용 가능
const ChildComponent = {
    template: `
        <div>
            <h3>{{ title }}</h3>
            <p>메시지: {{ message }}</p>
            <p>부모로부터 받은 숫자: {{ initialNumber }}</p>
            <button @click="updateNumber">숫자 업데이트</button>
        </div>
    `,
    props: {
        title: {
            type: String,
            required: true // 필수 prop
        },
        message: String, // 타입만 지정
        initialNumber: {
            type: Number,
            default: 0 // 기본값 지정
        }
    },
    data() {
        return {
            currentNumber: this.initialNumber // prop을 초기 데이터로 사용
        };
    },
    methods: {
        updateNumber() {
            this.currentNumber++;
            // prop은 직접 변경하지 않고, 이벤트를 통해 부모에게 알립니다.
            // this.$emit('number-updated', this.currentNumber); // 추후 Step3에서 상세 학습
        }
    },
    // 컴포넌트의 유효성 검사 (개발 모드에서 경고 출력)
    // props: {
    //     propA: Number,
    //     propB: [String, Number],
    //     propC: {
    //         type: String,
    //         required: true
    //     },
    //     propD: {
    //         type: Number,
    //         default: 100
    //     },
    //     propE: {
    //         type: Object,
    //         default: function () {
    //             return { message: 'hello' }
    //         }
    //     },
    //     propF: {
    //         validator: function (value) {
    //             return ['success', 'warning', 'danger'].indexOf(value) !== -1
    //         }
    //     }
    // }
};

new Vue({
    el: '#app',
    components: { // 지역 컴포넌트 등록
        'child-component': ChildComponent
    },
    data: {
        parentMessage: 'Vue2 컴포넌트 학습 중!',
        numberForChild: 10,
        buttonClickCounts: {}
    },
    methods: {
        handleButtonClick(count) {
            console.log(`my-button 컴포넌트가 ${count}번 클릭되었습니다.`);
            this.$set(this.buttonClickCounts, 'myButton', count); // 반응형으로 객체 속성 추가
        }
    }
});


// HTML (예상)
/*
<div id="app">
    <h1>{{ parentMessage }}</h1>

    <p>--- 전역 컴포넌트 ---</p>
    <my-button text="전역 버튼 1" @button-clicked="handleButtonClick"></my-button>
    <my-button :text="'전역 버튼 2 (클릭수: ' + (buttonClickCounts.myButton || 0) + ')'"></my-button>

    <p>--- 지역 컴포넌트 ---</p>
    <child-component
        title="자식 컴포넌트 제목"
        message="부모가 전달한 메시지"
        :initial-number="numberForChild"
    ></child-component>

    <child-component title="다른 자식 컴포넌트"></child-component>
</div>
*/

// Vue2 컴포넌트 통신
// Events ($emit), Custom Events, Vuex를 이용한 컴포넌트 간 통신

// 나쁜 예시: 전역 이벤트 버스($emit/$on)를 과도하게 사용하여 디버깅을 어렵게 만들거나, 복잡한 부모-자식 통신을 위해 `props`와 `emit`의 체인이 길어져 유지보수 어려움.
// 좋은 예시: `props`는 하향식, `$emit`은 상향식 통신에 사용하고, 복잡한 전역 상태 관리는 Vuex를 활용하여 예측 가능하고 관리하기 쉽게 만듭니다.

// --- 1. Prop Down, Event Up (부모 -> 자식, 자식 -> 부모 통신) ---

// 자식 컴포넌트
Vue.component('child-comp', {
    template: `
        <div style="border: 1px solid blue; padding: 10px; margin: 10px;">
            <h3>자식 컴포넌트</h3>
            <p>부모로부터 받은 메시지: <strong>{{ parentMsg }}</strong></p>
            <input type="text" v-model="childData">
            <button @click="sendToParent">부모에게 데이터 보내기</button>
        </div>
    `,
    props: ['parentMsg'], // 부모로부터 메시지를 받음
    data() {
        return {
            childData: ''
        };
    },
    methods: {
        sendToParent() {
            // $emit을 사용하여 'child-data-updated' 이벤트를 부모에게 발생시킵니다.
            // 두 번째 인자는 부모에게 전달할 데이터입니다.
            this.$emit('child-data-updated', this.childData);
            this.childData = ''; // 전송 후 초기화
        }
    }
});

// 부모 컴포넌트
new Vue({
    el: '#app-communication',
    data: {
        messageForChild: '안녕, 자식 컴포넌트!',
        receivedFromChild: ''
    },
    methods: {
        handleChildDataUpdated(data) {
            this.receivedFromChild = data;
            console.log('부모가 자식으로부터 받은 데이터:', data);
        }
    }
});

// --- 2. 전역 이벤트 버스 (Global Event Bus) ---
// Vue 인스턴스를 이벤트 버스로 활용하여 컴포넌트 간 직접적인 부모-자식 관계가 없는 경우에도 통신 가능.
// 단, 이벤트를 추적하기 어렵고 관리가 복잡해질 수 있어 남용은 피하는 것이 좋습니다.
const eventBus = new Vue(); // 빈 Vue 인스턴스를 이벤트 버스로 사용

Vue.component('component-a', {
    template: `
        <div style="border: 1px solid green; padding: 10px; margin: 10px;">
            <h3>컴포넌트 A</h3>
            <button @click="sendToB">컴포넌트 B에게 메시지 보내기</button>
        </div>
    `,
    methods: {
        sendToB() {
            eventBus.$emit('message-from-a', '안녕하세요, 컴포넌트 B!');
        }
    }
});

Vue.component('component-b', {
    template: `
        <div style="border: 1px solid red; padding: 10px; margin: 10px;">
            <h3>컴포넌트 B</h3>
            <p>A로부터 받은 메시지: <strong>{{ messageA }}</strong></p>
        </div>
    `,
    data() {
        return {
            messageA: ''
        };
    },
    created() {
        // 컴포넌트 A로부터 'message-from-a' 이벤트를 수신
        eventBus.$on('message-from-a', (msg) => {
            this.messageA = msg;
        });
    },
    beforeDestroy() {
        // 컴포넌트 파괴 전에 이벤트 리스너를 제거하여 메모리 누수 방지
        eventBus.$off('message-from-a');
    }
});

new Vue({
    el: '#app-eventbus'
});

// --- 3. Vuex (중앙 집중식 상태 관리) ---
// 대규모 애플리케이션에서 복잡한 전역 상태를 관리하기 위한 패턴 + 라이브러리.
// Flux 패턴에서 영감을 받았으며, 모든 컴포넌트가 공유하는 상태를 예측 가능하게 관리합니다.
// (Step5에서 상세 학습 예정)

// HTML (예상)
/*
<div id="app-communication">
    <h1>컴포넌트 통신 예시 (Prop Down, Event Up)</h1>
    <p>부모 컴포넌트에서 자식에게: {{ messageForChild }}</p>
    <p>부모 컴포넌트가 자식으로부터 받은 데이터: <strong>{{ receivedFromChild }}</strong></p>
    <child-comp :parent-msg="messageForChild" @child-data-updated="handleChildDataUpdated"></child-comp>
</div>

<div id="app-eventbus">
    <h1>컴포넌트 통신 예시 (전역 이벤트 버스)</h1>
    <component-a></component-a>
    <component-b></component-b>
</div>
*/

// Vue2 Vue Router
// SPA 구현을 위한 Vue Router 설정 및 동적 라우팅

// 나쁜 예시: 페이지 이동 시마다 전체 페이지를 새로 로드하여 사용자 경험을 저해하고, 비동기 데이터 로딩을 수동으로 관리하여 복잡도를 높임.
// 좋은 예시: Vue Router를 사용하여 SPA(Single Page Application)를 구현하고, 컴포넌트 기반 라우팅, 중첩 라우팅, 동적 라우팅으로 사용자 친화적인 내비게이션 제공.

// 1. Vue Router CDN 또는 npm으로 설치
// <script src="https://unpkg.com/vue-router@3"></script>

// 2. 라우팅을 위한 컴포넌트 정의
const Home = { template: '<div><h1>홈 페이지</h1><p>환영합니다!</p></div>' };
const About = { template: '<div><h1>회사 소개</h1><p>저희 회사에 대해 알아보세요.</p></div>' };
const User = {
    template: `
        <div>
            <h1>사용자 정보: {{ $route.params.id }}</h1>
            <p>이름: {{ userName }}</p>
            <button @click="goBack">뒤로 가기</button>
            <router-view></router-view> <!-- 중첩 라우팅을 위한 placeholder -->
        </div>
    `,
    data() {
        return {
            userName: ''
        };
    },
    // 라우트 파라미터가 변경될 때마다 데이터를 업데이트
    watch: {
        '$route': 'fetchData' // $route 객체 변경 감지하여 fetchData 메서드 호출
    },
    created() {
        this.fetchData();
    },
    methods: {
        fetchData() {
            // 실제 데이터는 API 호출을 통해 가져옵니다.
            const userId = this.$route.params.id;
            console.log(`사용자 ID ${userId}의 데이터를 가져옵니다.`);
            if (userId === '1') {
                this.userName = 'Alice';
            } else if (userId === '2') {
                this.userName = 'Bob';
            } else {
                this.userName = '알 수 없는 사용자';
            }
        },
        goBack() {
            this.$router.go(-1); // 이전 페이지로 이동
        }
    },
    // 중첩 라우팅 예시 (사용자 상세 정보)
    // <router-link :to="{ name: 'userPosts', params: { id: $route.params.id }}">게시물 보기</router-link>
    // <router-link :to="{ name: 'userProfile', params: { id: $route.params.id }}">프로필 상세</router-link>
};

const UserPosts = { template: '<div><h2>{{ $route.params.id }}의 게시물 목록</h2></div>' };
const UserProfile = { template: '<div><h2>{{ $route.params.id }}의 프로필 상세</h2></div>' };


// 3. 라우트 정의
const routes = [
    { path: '/', component: Home },
    { path: '/about', component: About },
    {
        path: '/user/:id', // 동적 라우팅 파라미터 (:id)
        component: User,
        name: 'user', // 라우트 이름 지정
        children: [ // 중첩 라우팅
            {
                path: 'posts',
                component: UserPosts,
                name: 'userPosts'
            },
            {
                path: 'profile',
                component: UserProfile,
                name: 'userProfile'
            }
        ]
    },
    { path: '*', redirect: '/' } // 매칭되는 라우트가 없으면 홈으로 리다이렉트
];

// 4. Vue Router 인스턴스 생성
const router = new VueRouter({
    mode: 'history', // URL에 # 없이 깔끔하게 사용 (서버 설정 필요)
    routes // `routes: routes`와 동일
});

// 5. Vue 인스턴스에 라우터 연결
new Vue({
    el: '#app-router',
    router, // `router: router`와 동일
    data: {
        dynamicUserId: '1' // 동적 사용자 ID
    },
    methods: {
        goToUser(id) {
            this.$router.push(`/user/${id}`); // 프로그래밍 방식으로 라우트 이동
        },
        goToUserProfile(id) {
            this.$router.push({ name: 'userProfile', params: { id: id }});
        }
    }
});


// HTML (예상)
