        <router-link to="/">Home</router-link> |
        <router-link to="/about">About</router-link> |
        <router-link to="/user/1">User 1</router-link> |
        <router-link to="/user/2">User 2</router-link>
    </p>

    <p>
        <input type="number" v-model="dynamicUserId">
        <button @click="goToUser(dynamicUserId)">사용자 페이지로 이동</button>
        <button @click="goToUserProfile(dynamicUserId)">사용자 프로필 상세로 이동</button>
    </p>

    <hr>
    <router-view></router-view> <!-- 현재 라우트에 해당하는 컴포넌트가 렌더링될 위치 -->
</div>
*/

// Vue3 Pinia (상태 관리)
// Vue3 권장 상태 관리 라이브러리 Pinia의 개념 및 활용

// 나쁜 예시: 전역 변수나 컴포넌트 간 직접적인 통신으로 복잡한 애플리케이션의 상태를 관리하여 디버깅이 어렵고 상태 변화 추적이 불가능.
// 좋은 예시: Pinia를 사용하여 애플리케이션의 모든 컴포넌트가 공유하는 상태를 중앙 집중식으로 관리하고, 모듈화된 스토어와 예측 가능한 상태 변화를 통해 안정적인 애플리케이션 구축.

// Pinia는 Vuex 5의 새로운 이름이며, Vue3에서 Vuex를 대체하는 것을 목표로 합니다.
// Vuex에 비해 더 가볍고, 더 직관적인 API, TypeScript 완벽 지원 등의 장점이 있습니다.

// 1. Pinia 설치 (npm 또는 CDN)
// npm: `npm install pinia`
// CDN: <script src="https://unpkg.com/pinia@2"></script> (예시)

// 2. Pinia Store 정의 (defineStore)
// defineStore 함수는 스토어의 ID와 옵션 객체를 받습니다.
const useCounterStore = Pinia.defineStore('counter', {
    // state는 스토어의 데이터를 정의합니다. (Vue 컴포넌트의 data와 유사)
    state: () => ({
        count: 0,
        name: 'Pinia User'
    }),
    // getters는 state를 기반으로 계산된 값을 제공합니다. (Vue 컴포넌트의 computed와 유사)
    getters: {
        doubleCount: (state) => state.count * 2,
        // 다른 getter를 참조할 수도 있습니다.
        doubleCountPlusOne() {
            return this.doubleCount + 1;
        },
        // getters는 항상 첫 번째 인자로 state를 받으며, 두 번째 인자로 다른 getters를 받습니다.
        // `this`로도 다른 getter에 접근할 수 있습니다.
    },
    // actions는 state를 변경하는 로직이나 비동기 작업을 수행합니다. (Vue 컴포넌트의 methods와 유사)
    actions: {
        increment() {
            this.count++; // `this`를 사용하여 state에 접근
        },
        decrement() {
            this.count--;
        },
        async incrementAndSayHello() {
            // 비동기 작업 예시
            await new Promise(resolve => setTimeout(resolve, 1000));
            this.increment();
            alert(`Count는 ${this.count}로 증가했습니다. 안녕하세요!`);
        },
        setCount(amount) {
            this.count = amount;
        }
    }
});

const useUserStore = Pinia.defineStore('user', {
    state: () => ({
        firstName: 'John',
        lastName: 'Doe'
    }),
    getters: {
        fullName: (state) => `${state.firstName} ${state.lastName}`
    },
    actions: {
        setFirstName(name) {
            this.firstName = name;
        },
        setLastName(name) {
            this.lastName = name;
        }
    }
});


// 3. Vue 앱 인스턴스 생성 및 Pinia 연결
const app = Vue.createApp({
    template: `
        <div id="app-pinia">
            <h1>Pinia 상태 관리 예시</h1>
            <counter-component></counter-component>
            <user-profile-component></user-profile-component>
        </div>
    `,
    components: {
        'counter-component': {
            template: `
                <div style="border: 1px solid gray; padding: 10px; margin: 10px;">
                    <h3>카운터 컴포넌트</h3>
                    <p>현재 카운트: {{ counterStore.count }}</p>
                    <p>두 배 카운트 (getter): {{ counterStore.doubleCount }}</p>
                    <p>두 배 카운트 + 1 (getter): {{ counterStore.doubleCountPlusOne }}</p>
                    <button @click="counterStore.increment">증가</button>
                    <button @click="counterStore.decrement">감소</button>
                    <button @click="counterStore.incrementAndSayHello">1초 후 증가 & 인사</button>
                    <button @click="counterStore.setCount(100)">100으로 설정</button>
                </div>
            `,
            setup() {
                const counterStore = useCounterStore(); // 스토어 사용

                // 스토어의 state를 반응성 속성으로 직접 참조할 경우 `storeToRefs` 사용 권장
                // const { count, name } = Pinia.storeToRefs(counterStore);

                return {
                    counterStore
                };
            }
        },
        'user-profile-component': {
            template: `
                <div style="border: 1px solid blue; padding: 10px; margin: 10px;">
                    <h3>사용자 프로필 컴포넌트</h3>
                    <p>이름: {{ userStore.fullName }}</p>
                    <p>스토어의 이름: {{ counterStore.name }}</p>
                    <input type="text" :value="userStore.firstName" @input="event => userStore.setFirstName(event.target.value)" placeholder="First Name">
                    <input type="text" :value="userStore.lastName" @input="event => userStore.setLastName(event.target.value)" placeholder="Last Name">
                    <input type="text" :value="counterStore.name" @input="event => counterStore.name = event.target.value" placeholder="Counter Store Name">
                </div>
            `,
            setup() {
                const userStore = useUserStore();
                const counterStore = useCounterStore(); // 다른 스토어 사용 가능

                return {
                    userStore,
                    counterStore
                };
            }
        }
    }
});

const pinia = Pinia.createPinia(); // Pinia 인스턴스 생성
app.use(pinia); // Pinia를 Vue 앱에 연결
app.mount('#app-pinia');

// Pinia의 주요 특징 및 장점:
// - 모듈화: 각 스토어가 독립적으로 작동하여 코드 구성이 용이합니다.
// - TypeScript 지원: Vuex보다 훨씬 강력한 TypeScript 지원을 제공합니다.
// - 가벼움: 초기 로드 시 `state`만 필요하며, `getters`와 `actions`는 필요할 때만 로드됩니다.
// - 단순한 API: Vue3 Composition API와 유사하게 `setup` 함수 내에서 `useStore()` 훅을 사용하여 쉽게 접근합니다.
// - 플러그인: 스토어 확장 기능을 제공합니다.
// - 서버 사이드 렌더링 (SSR) 지원.

// Vue3 Life Cycle Hooks (Composition API)
// `onMounted`, `onUpdated` 등 Composition API 기반 생명주기 훅 활용

// 나쁜 예시: 컴포넌트 라이프사이클을 이해하지 못하고, 부적절한 시점에 DOM 조작이나 비동기 요청을 수행하여 오류를 유발하거나 성능 저해.
// 좋은 예시: 각 라이프사이클 훅의 역할과 실행 시점을 정확히 이해하고, 적절한 훅에서 필요한 작업을 수행하여 안정적이고 효율적인 컴포넌트 구현.

// Vue3의 Composition API에서는 라이프사이클 훅이 `on` 접두사를 가진 함수로 제공됩니다.
// 이 훅들은 `setup()` 함수 내에서만 호출되어야 합니다.

const { createApp, ref, onBeforeMount, onMounted, onBeforeUpdate, onUpdated, onBeforeUnmount, onUnmounted, onErrorCaptured } = Vue;

const LifecycleExample = {
    template: `
        <div style="border: 1px solid #ccc; padding: 15px; margin: 15px;">
            <h2>라이프사이클 예제 컴포넌트 (Composition API)</h2>
            <p>메시지: {{ message }}</p>
            <button @click="updateMessage">메시지 업데이트</button>
            <!-- $parent.$data.showComponent = false; 를 통해 부모 컴포넌트 상태를 변경하여 언마운트 가능 -->
        </div>
    `,
    setup() {
        const message = ref('초기 메시지');
        let timer = null;

        // --- 1. Creation (생성) 단계 훅 ---
        // setup() 함수 자체는 Options API의 `beforeCreate`와 `created` 훅 사이에 실행됩니다.
        // `beforeCreate`와 `created`는 Composition API에 직접적인 대응 훅이 없습니다.
        // 대신 `setup()`에서 반응형 데이터 선언, computed, watch, provide/inject 등을 설정합니다.
        console.log('[Lifecycle] setup: 컴포넌트 생성 전 실행'); // `beforeCreate`보다 먼저 실행

        // --- 2. Mounting (마운트) 단계 훅 ---
        onBeforeMount(() => {
            console.log('[Lifecycle] onBeforeMount: DOM에 마운트되기 전');
            // 아직 DOM에 접근할 수 없습니다.
        });

        onMounted(() => {
            console.log('[Lifecycle] onMounted: DOM에 마운트 완료');
            // 컴포넌트가 실제 DOM에 부착된 후. DOM 관련 작업이나 외부 라이브러리 연동에 사용.
            // 예: `this.$el` 대신 `document.querySelector` 등을 사용하거나, 템플릿 참조 변수(ref) 사용
            document.querySelector('.lifecycle-example-component-container').style.backgroundColor = '#e6f7ff'; // 부모의 DOM을 조작 (예시)
            timer = setInterval(() => {
                message.value = '메시지 자동 업데이트: ' + new Date().toLocaleTimeString();
            }, 3000);
        });

        // --- 3. Updating (업데이트) 단계 훅 ---
        onBeforeUpdate(() => {
            console.log('[Lifecycle] onBeforeUpdate: 데이터 변경으로 DOM 업데이트 전');
            // 데이터가 변경되었고 가상 DOM이 다시 렌더링될 준비가 되었지만, 실제 DOM은 아직 업데이트되지 않았습니다.
        });

        onUpdated(() => {
            console.log('[Lifecycle] onUpdated: DOM 업데이트 완료');
            // 데이터 변경으로 인해 실제 DOM이 업데이트된 후.
        });

        // --- 4. Unmounting (언마운트) 단계 훅 ---
        onBeforeUnmount(() => {
            console.log('[Lifecycle] onBeforeUnmount: 인스턴스 소멸 전');
            // 컴포넌트가 파괴되기 직전.
            // 메모리 누수를 방지하기 위해 `setInterval`, `setTimeout`, 이벤트 리스너 등을 여기서 정리합니다.
            if (timer) {
                clearInterval(timer);
                console.log('  타이머가 정리되었습니다.');
            }
            console.log('  이벤트 리스너 등 정리 시작.');
        });

        onUnmounted(() => {
            console.log('[Lifecycle] onUnmounted: 인스턴스 소멸 완료');
            // 인스턴스가 완전히 파괴된 후. 모든 디렉티브 바인딩, 이벤트 리스너 등이 제거됩니다.
        });

        // --- 에러 처리 훅 ---
        onErrorCaptured((err, instance, info) => {
            console.error('[Lifecycle] onErrorCaptured: 컴포넌트에서 에러 발생!', err, instance, info);
            // 에러 로깅, 사용자에게 에러 메시지 표시 등
            return true; // 에러가 상위 컴포넌트로 전파되는 것을 중지 (선택 사항)
        });

        const updateMessage = () => {
            message.value = '수동으로 업데이트됨: ' + new Date().toLocaleTimeString();
        };

        return {
            message,
            updateMessage
        };
    }
};

const AppRoot = {
    template: `
        <div id="app-lifecycle-root">
            <h1>Vue3 라이프사이클 훅 예시 (Composition API)</h1>
            <button @click="showComponent = !showComponent">
                컴포넌트 {{ showComponent ? '숨기기' : '보이기' }}
            </button>
            <div class="lifecycle-example-component-container">
                <lifecycle-example v-if="showComponent"></lifecycle-example>
            </div>
            <button @click="triggerError">에러 발생시키기 (내부 컴포넌트)</button>
            <error-child-component v-if="showComponent" />
        </div>
    `,
    components: {
        'lifecycle-example': LifecycleExample,
        'error-child-component': {
            template: `
                <div style="border: 1px dashed red; padding: 10px; margin: 10px;">
                    <h4>에러 발생 자식 컴포넌트</h4>
                    <button @click="triggerRuntimeError">런타임 에러 발생</button>
                </div>
            `,
            setup() {
                const triggerRuntimeError = () => {
                    throw new Error('자식 컴포넌트에서 발생한 런타임 에러!');
                };
                return { triggerRuntimeError };
            }
        }
    },
    setup() {
        const showComponent = ref(true);
        const triggerError = () => {
            console.log('에러 발생 버튼 클릭');
            // 이 버튼은 ErrorChildComponent 내의 버튼과 별개입니다.
            // 실제 에러는 ErrorChildComponent 내의 버튼을 통해 발생시킵니다.
        };

        return {
            showComponent,
            triggerError
        };
    }
};


createApp(AppRoot).mount('#app');

